
/* ==================== toggleTrain (async + askPrompt) ==================== */
async function toggleTrain(trainId){
  const tr = trainings.find(t => t.id === trainId);
  if(!tr || !isTrainScheduled(tr, selectedDate)) return;
  if(isoDate(selectedDate) > isoDate(TODAY)){ toast('🔒 Будущую тренировку отметить нельзя'); return; }
  const key = isoDate(selectedDate);
  const wasDone = isTrainDone(selectedDate, tr);
  if(wasDone){
    const c = completions[key] && completions[key][tr.id];
    const xpA = c ? c.xpAwarded : 0;
    setTrainDone(selectedDate, tr.id, false);
    if(xpA > 0) removeXp(xpA, tr.name, {exercises:c?.exercises || tr.exercises});
  } else {
    const eff = getEffectiveTrain(tr, selectedDate);
    const exs = eff.exercises || [];
    let xp = calcTrainXp(tr, eff);
    const roundsInfo = {};
    const actualExs = [];
    for(let idx = 0; idx < exs.length; idx++){
      const e = exs[idx];
      if(e.type === 'rounds'){
        const v = await askPrompt('🔁 «'+e.name+'»\nСколько кругов выполнили?', '0');
        const r = parseInt(v, 10) || 0;
        roundsInfo[idx] = r;
        xp += xpForOneRound(e) * r;
        actualExs.push({...e, actualRounds: r});
        continue;
      }
      if(isXValue(e.reps) || isXValue(e.weight)){
        let vReps = 0, vWeight = 0;
        if(isXValue(e.reps)){
          const v = await askPrompt('«'+e.name+'»\nПовторов за подход?', '0');
          vReps = parseInt(v, 10) || 0;
        }
        if(isXValue(e.weight)){
          const v = await askPrompt('«'+e.name+'»\nВес, кг?', '0');
          vWeight = parseFloat(v) || 0;
        }
        const sets = +e.sets || 1;
        const ex = exercises.find(x => x.id === e.exId);
        const sidesMult = ex && ex.twoSides ? 2 : 1;
        let exXp = 0;
        if(ex && ex.format === 'weight'){
          exXp += xpFromWeight(vWeight, profile.weight||70, vReps) * sets * sidesMult;
        } else if(ex){
          exXp += xpFromReps(vReps) * sets * sidesMult;
        }
        xp += exXp;
        actualExs.push({...e,
          repsPerSet: new Array(sets).fill(vReps),
          weightPerSet: new Array(sets).fill(vWeight),
          reps: vReps, weight: vWeight
        });
      } else {
        actualExs.push(e);
      }
    }
    xp = Math.round(xp * 100) / 100;
    setTrainDone(selectedDate, tr.id, true, xp, JSON.parse(JSON.stringify(actualExs)));
    if(Object.keys(roundsInfo).length){
      if(completions[key] && completions[key][tr.id]){
        completions[key][tr.id].rounds = roundsInfo;
        store.set('completions', completions);
      }
    }
    if(xp > 0) addXp(xp, tr.name, {exercises:actualExs});
    const regularExs = actualExs.filter(e => e.type !== 'rounds');
    const newPRs = checkNewPRs(regularExs, key);
    if(newPRs.length > 0){
      setTimeout(() => {
        newPRs.forEach((pr, i) => setTimeout(() => prFly(pr.exName, pr.display), i * 800));
      }, 500);
    }
  }
  renderTrainings(); renderWeek(); renderMonth(); renderStats();
}

/* ==================== ВЫПОЛНЕНИЕ ==================== */
let execState = null;

let workoutClock = null;

function formatWorkoutTime(seconds){
  const whole = Math.max(0, Math.floor(seconds || 0));
  return whole < 3600 ? fmt(whole) : Math.floor(whole / 3600)+':'+fmt(whole % 3600);
}
function workoutElapsed(at = Date.now()){
  if(!workoutClock) return 0;
  const end = workoutClock.endedAt ?? at;
  return Math.floor(Math.max(0, end - workoutClock.startedAt) / 1000);
}
function renderWorkoutClock(){
  const host = document.getElementById('execElapsed');
  host.hidden = !workoutClock;
  if(workoutClock){
    document.getElementById('execElapsedValue').textContent = formatWorkoutTime(workoutElapsed());
    document.getElementById('execEndEarly').hidden = workoutClock.endedAt !== null; document.getElementById('duCancelWorkout').hidden = workoutClock.endedAt !== null && !duPendingSave;
  }
}
function startWorkoutClock(){
  if(workoutClock) return;
  workoutClock = {startedAt:Date.now(), endedAt:null, timer:setInterval(renderWorkoutClock, 250)};
  renderWorkoutClock();
}
document.addEventListener('visibilitychange', () => { if(!document.hidden) renderWorkoutClock(); });
function finishWorkoutClock(at = Date.now()){
  if(workoutClock && workoutClock.endedAt === null){
    workoutClock.endedAt = at;
    clearInterval(workoutClock.timer);
    renderWorkoutClock();
  }
  return workoutElapsed();
}
function finishActiveWorkout(){
  if(!workoutClock || workoutClock.endedAt !== null) return;
  if(amrapRun){ confirmAmrapFinish(); return; }
  if(fujiRun){
    if(confirm('Завершить и сохранить текущий результат?')) fujiFinish();
    return;
  }
  const state = execState;
  if(!state || state.finishingSet || !confirm('Завершить тренировку? В результат войдут отмеченные подходы и круги.')) return;
  if(state.roundTimer){
    recordRoundBlock(state, state.exercises[state.currentIndex]);
  } else {
    recordPartialExercise(state);
  }
  finishExecution();
}
function resetWorkoutClock(){
  if(workoutClock) clearInterval(workoutClock.timer);
  workoutClock = null;
  renderWorkoutClock();
}


function startTrainExecution(trainId, sessionPlan = null){
  if(execState) return;
  const tr = sessionPlan || trainings.find(t => t.id === trainId);
  if(!tr || !isTrainScheduled(tr, selectedDate) || isTrainDone(selectedDate, tr)) return;
  if(isoDate(selectedDate) > isoDate(TODAY)){ toast('🔒 Будущую тренировку запустить нельзя'); return; }
  const eff = getEffectiveTrain(tr, selectedDate);
  if(!eff.exercises || !eff.exercises.length){ toast('Нет упражнений'); return; }
  const exs = eff.exercises.map(e => {
    if(e.type === 'rounds'){
      return {
        type: 'rounds',
        name: e.name,
        time: e.time,
        blockExMapped: (e.blockEx || []).map(be => {
          const ex = exercises.find(x => x.id === be.exId);
          return {
            ...be,
            exName: ex ? ex.name : '?',
            exFormat: ex ? ex.format : 'reps',
            twoSides: ex ? !!ex.twoSides : false
          };
        })
      };
    }
    const ex = exercises.find(x => x.id === e.exId);
    return {
      ...e,
      exName: ex ? ex.name : '?',
      exFormat: ex ? ex.format : 'reps',
      twoSides: ex ? !!ex.twoSides : false,
    };
  });
  execState = {
    laps: [], setLog: [],
    trainId, sessionPlan, dateKey: isoDate(selectedDate), trainName: tr.name,
    timerOptions:{prep:10, automatic:true, advance:false, sound:true, vibration:true, ...store.get('execTimerOptions', {})},
    setWorkMs:0, durationBySet:[], finishingSet:false,
    exercises: JSON.parse(JSON.stringify(exs)),
    currentIndex: 0, currentSet: 1, currentSide: 1,
    currentRounds: 0, roundTimer: null,
    currentRepsPerSet: [],
    currentWeightPerSet: [],
    completed: [],
    phase: 'idle',
    timer: { remaining: 0, total: 0, running: false, int: null, workStarted:null }
  };
  document.getElementById('execScreen').classList.add('on');
  document.getElementById('execTitle').textContent = tr.name;
  renderExecScreen();
}

function closeExecScreen(){
  if(execState && !execState.saved){
    const underway = execState.phase !== 'idle' || execState.roundTimer || execState.completed.length;
    if(underway && !confirm('Закрыть тренировку? Прогресс не сохранится.')) return;
    stopExecClock(execState);
    clearInterval(execState.roundTimer?.int);
    releaseExecWakeLock(execState);
  }
  document.getElementById('execScreen').classList.remove('on');
  resetWorkoutClock();
  closeModal('m-exec-timer');
  execState = null;
}
function renderExecScreen(){
  if(!execState){ return; }
  const body = document.getElementById('execBody');
  const footer = document.getElementById('execFooter');
  const progressTxt = document.getElementById('execProgressTxt');
  const totalEx = execState.exercises.length;
  const curIdx = execState.currentIndex;
  const item = execState.exercises[curIdx];
  if(!item){ finishExecution(); return; }
  if(progressTxt){
    const circuit = execState.intervalCircuitLength;
    progressTxt.textContent = circuit
      ? 'Круг ' + (Math.floor(curIdx/circuit)+1) + '/' + Math.ceil(totalEx/circuit) + ' · ' + (curIdx%circuit+1) + '/' + circuit
      : (curIdx+1)+'/'+totalEx;
  }

  if(item.type === 'rounds'){
    let planHtml = '<div class="exec-plan-list">';
    execState.exercises.forEach((ex, idx) => {
      let cls = 'exec-plan-item';
      let icon = idx + 1;
      if(idx < curIdx){ cls += ' done'; icon = '✓'; }
      else if(idx === curIdx){ cls += ' active'; icon = '▶'; }
      const label = ex.type === 'rounds' ? '🔁 ' + ex.name : ex.exName;
      const dose = ex.type === 'rounds' ? Math.round(ex.time/60) + ' мин' : '';
      planHtml += '<div class="'+cls+'">'+
        '<div class="exec-plan-check">'+icon+'</div>'+
        '<div class="exec-plan-name">'+label+'</div>'+
        '<div class="exec-plan-dosage">'+dose+'</div>'+
      '</div>';
    });
    planHtml += '</div>';
    const rounds = execState.currentRounds || 0;
    const running = execState.roundTimer && execState.roundTimer.running;
    const remaining = execState.roundTimer ? Math.max(0, execState.roundTimer.remaining) : item.time;
    body.innerHTML =
      '<div class="exec-global-bar"><i style="width:'+Math.round(curIdx/totalEx*100)+'%"></i></div>'+
      planHtml+
      '<div class="exec-focus">'+
        '<div class="exec-ex-number">Круговая '+(curIdx+1)+' из '+totalEx+'</div>'+
        '<div class="exec-ex-name">'+item.name+'</div>'+
        '<div class="exec-round-count">'+rounds+'</div>'+
        '<div class="exec-round-lbl">'+(rounds === 1 ? 'круг' : rounds < 5 ? 'круга' : 'кругов')+'</div>'+
        '<div class="exec-phase '+(running?'work':'')+'" style="margin-top:6px">'+(running ? '⏱ Таймер идёт' : 'Готов к старту')+'</div>'+
        '<div class="exec-timer">'+fmt(remaining)+'</div>'+
        '<div class="exec-round-list">'+
          item.blockExMapped.map(be => {
            const dose = [];
            if(be.reps) dose.push(be.reps+' повт');
            if(be.time) dose.push(be.time+' с');
            if(be.weight) dose.push(be.weight+' кг');
            if(be.twoSides) dose.push('×2');
            if(!dose.length) dose.push('—');
            return '<div class="exec-round-ex"><span class="exec-round-ex-name">'+be.exName+'</span><span class="exec-round-ex-dose">'+dose.join(' · ')+'</span></div>';
          }).join('')+
        '</div>'+
      '</div>';
    if(running){
      footer.innerHTML =
        '<button class="btn btn-primary exec-finish" onclick="roundComplete()" style="padding:var(--space-4);font-size:var(--font-lg)">✓ Круг завершён ('+(rounds+1)+')</button>'+
        '<button class="btn btn-full" style="margin-top:8px" onclick="endRoundBlock(false)">Завершить круговую</button>';
    } else if(rounds > 0){
      footer.innerHTML =
        '<button class="btn btn-primary exec-finish" onclick="endRoundBlock(false)">✓ Завершить ('+rounds+' '+(rounds===1?'круг':rounds<5?'круга':'кругов')+')</button>';
    } else {
      footer.innerHTML = '<button class="btn btn-primary exec-finish" onclick="startRoundBlock()">▶ Начать круги (⏱ '+Math.round(item.time/60)+' мин)</button>';
    }
    return;
  }

  const hasX = ['sets','time','rest'].some(f => isXValue(item[f]));
  if(hasX && !item._xResolved){
    body.innerHTML =
      '<div class="exec-global-bar"><i style="width:0%"></i></div>'+
      '<div style="text-align:center;font-size:44px;margin:20px 0">✏️</div>'+
      '<div class="exec-ex-name">'+item.exName+'</div>'+
      '<div class="note" style="text-align:center;margin-bottom:16px">Задай параметры'+(item.twoSides?' (значения — на одну сторону)':'')+'<br><b>Повторы и вес</b> спросим <b>после каждого подхода</b></div>'+
      '<div id="xFormContainer" style="max-width:420px;margin:0 auto;width:100%"></div>';
    const form = document.getElementById('xFormContainer');
    const fields = [];
    if(isXValue(item.sets)) fields.push({key:'sets', label:'Подходы', placeholder:'3'});
    if(isXValue(item.time)) fields.push({key:'time', label:'Время, сек', placeholder:'60'});
    if(isXValue(item.rest)) fields.push({key:'rest', label:'Отдых, сек', placeholder:'60'});
    form.innerHTML = fields.map(f =>
      '<div class="field-group"><label class="field-label">'+f.label+'</label><input class="field-input" type="number" id="xInput_'+f.key+'" placeholder="'+f.placeholder+'"></div>'
    ).join('') +
    '<button class="btn btn-primary btn-full" style="margin-top:12px;padding:14px" onclick="applyXForm()">▶ Начать упражнение</button>';
    footer.innerHTML = '';
    return;
  }

  let planHtml = '<div class="exec-plan-list">';
  execState.exercises.forEach((ex, idx) => {
    let cls = 'exec-plan-item';
    let icon = idx + 1;
    if(idx < curIdx){ cls += ' done'; icon = '✓'; }
    else if(idx === curIdx){ cls += ' active'; icon = '▶'; }
    let dose = [];
    const label = ex.type === 'rounds' ? '🔁 '+ex.name : ex.exName;
    if(ex.type === 'rounds'){ dose.push('🔁 '+Math.round(ex.time/60)+' мин'); }
    else {
      if(ex.sets) dose.push(ex.sets + '×');
      if(ex.reps) dose.push(ex.reps + 'повт');
      if(ex.time) dose.push(ex.time + 'с');
      if(ex.twoSides) dose.push('×2');
    }
    planHtml += '<div class="'+cls+'">'+
      '<div class="exec-plan-check">'+icon+'</div>'+
      '<div class="exec-plan-name">'+label+'</div>'+
      '<div class="exec-plan-dosage">'+dose.join(' ')+'</div>'+
    '</div>';
  });
  planHtml += '</div>';

  const totalSets = +item.sets || 1;
  let dotsHtml = '<div class="exec-dots">';
  for(let i = 1; i <= totalSets; i++){
    let cls = 'exec-dot';
    if(i < execState.currentSet) cls += ' done';
    else if(i === execState.currentSet) cls += ' active';
    dotsHtml += '<div class="'+cls+'"></div>';
  }
  dotsHtml += '</div>';

  let sideHtml = '';
  if(item.twoSides){
    sideHtml = '<div class="exec-side-indicator">'+
      '<span class="exec-side '+(execState.currentSide===1?'active':'')+'">Сторона 1</span>'+
      '<span class="exec-side-sep">/</span>'+
      '<span class="exec-side '+(execState.currentSide===2?'active':'')+'">Сторона 2</span>'+
    '</div>';
  }

  let phaseText = 'Готов', phaseClass = '';
  if(execState.phase === 'prep'){
    phaseText = 'Подготовка';
    phaseClass = 'prep';
  }
  if(execState.phase === 'work'){
    phaseText = item.twoSides ? 'Работа · Сторона '+execState.currentSide : 'Работа';
    phaseClass = 'work';
  }
  if(execState.phase === 'rest'){
    phaseText = item.twoSides && execState.currentSide === 2 ? 'Отдых перед стороной 2' : 'Отдых';
    phaseClass = 'rest';
  }

  if(execState.timer.paused) phaseText += ' · Пауза';
  if(execState.phase !== 'idle' && execState.timer.total > 0 &&
      !execState.timer.running && !execState.timer.paused) phaseText += ' · Время вышло';
  const timerDisplay = execState.phase === 'idle' && execIsTimed(item) ?
    fmt(Number(item.time)) : fmt(Math.max(0, execState.timer.remaining));
  const globalPct = Math.round(((curIdx + (execState.currentSet-1)/totalSets) / totalEx) * 100);

  const dosageHtmlParts = [];
  if(item.reps) dosageHtmlParts.push('<div class="exec-dosage-item"><div class="lbl">Повторы</div><div class="val">'+(isXValue(item.reps)?'X':item.reps)+'</div></div>');
  if(item.time) dosageHtmlParts.push('<div class="exec-dosage-item"><div class="lbl">Время</div><div class="val">'+item.time+'с</div></div>');
  if(item.weight) dosageHtmlParts.push('<div class="exec-dosage-item"><div class="lbl">Вес</div><div class="val">'+(isXValue(item.weight)?'X':item.weight)+'кг</div></div>');

  const shownReps = execState.currentRepsPerSet[execState.currentSet - 1];
  const shownWeight = execState.currentWeightPerSet[execState.currentSet - 1];
  let enteredHtml = '';
  if(shownReps != null || shownWeight != null){
    enteredHtml = '<div class="note" style="margin-top:8px;text-align:center">'+
      'Подход '+execState.currentSet+': '+
      (shownReps != null ? '<b>'+shownReps+'</b> повт' : '')+
      (shownReps != null && shownWeight != null ? ' · ' : '')+
      (shownWeight != null ? '<b>'+shownWeight+'</b> кг' : '')+
    '</div>';
  }

  body.innerHTML =
    '<div class="exec-global-bar"><i style="width:'+globalPct+'%"></i></div>'+
    planHtml+
    '<div class="exec-focus">'+
      '<div class="exec-ex-number">Упражнение '+(curIdx+1)+' из '+totalEx+'</div>'+
      '<div class="exec-ex-name">'+item.exName+'</div>'+
      boneExecImage(item)+
      dotsHtml+
      sideHtml+
      '<div class="exec-phase '+phaseClass+'">'+phaseText+'</div>'+
      '<div class="exec-timer">'+timerDisplay+'</div>'+
      '<div class="exec-dosage">'+
        '<div class="exec-dosage-row">'+dosageHtmlParts.join('')+'</div>'+
        enteredHtml+
      '</div>'+
    '</div>';

  const pause = execState.timer.running || execState.timer.paused || execState.timer.workStarted !== null ?
    '<button class="btn" onclick="toggleExecTimer()">' + (execState.timer.paused ? '▶ Продолжить' : '⏸ Пауза') + '</button>' : '';
  if(execState.phase === 'idle'){
    const auto = execState.timerOptions.automatic && execIsTimed(item);
    const startLabel = auto ? '▶ Запустить интервалы' : '▶ Начать подход ' + execState.currentSet;
    const prep = execState.timerOptions.prep;
    const preview = execIsTimed(item) ?
      totalSets + ' × ' + fmt(Number(item.time)) + ' · отдых ' + fmt(Number(item.rest) || 0) : '';
    const preshow = [prep > 0 ? 'Подготовка ' + prep + ' с' : '', preview].filter(Boolean).join(' · ');
    footer.innerHTML = (preshow ? '<div class="note timer-start-preview">'+preshow+'</div>' : '') +
      '<div class="exec-controls"><button class="btn btn-primary" onclick="execStartWork()">'+startLabel+'</button>'+
      '<button class="btn" onclick="openExecTimerSettings()">Настройки таймера</button></div>';
  } else if(execState.phase === 'work'){
    footer.innerHTML = '<div class="exec-controls">'+
      '<button class="btn btn-primary" onclick="execFinishSet()">Подход готов</button>'+
      pause+'</div><button class="btn btn-full exec-timer-sub" onclick="execSkipExercise()">Пропустить упражнение</button>';
  } else {
    const label = execState.phase === 'prep' ? 'Начать сейчас' :
      (execState.timer.running || execState.timer.paused ? 'Пропустить отдых' : 'Следующий подход');
    footer.innerHTML = '<div class="exec-controls"><button class="btn btn-primary" onclick="execSkipRest()">'+label+'</button>'+pause+'</div>';
  }
}
function applyXForm(){
  const item = execState.exercises[execState.currentIndex];
  ['sets','time','rest'].forEach(f => {
    if(isXValue(item[f])){
      const inp = document.getElementById('xInput_'+f);
      if(inp && inp.value) item[f] = +inp.value || 0;
    }
  });
  item._xResolved = true;
  renderExecScreen();
}

function startRoundBlock(){
  const item = execState.exercises[execState.currentIndex];
  if(!item || item.type !== 'rounds') return;
  startWorkoutClock();
  if(execState.roundTimer && execState.roundTimer.int) clearInterval(execState.roundTimer.int);
  execState.currentRounds = 0;
  execState.lapStart = Date.now(); beep(950,.18);
  const state = execState;
  const timer = {remaining:item.time, total:item.time, running:true, deadline:Date.now()+item.time*1000, int:null};
  state.roundTimer = timer;
  timer.int = setInterval(() => {
    if(execState !== state || state.roundTimer !== timer) return;
    timer.remaining = Math.max(0, Math.ceil((timer.deadline - Date.now()) / 1000));
    const display = document.querySelector('#execBody .exec-timer');
    if(display) display.textContent = fmt(timer.remaining);
    if(!timer.remaining) endRoundBlock(true);
  }, 200);
  renderExecScreen();
}
function roundComplete(){
  if(!execState?.roundTimer?.running) return;
  execState.currentRounds = (execState.currentRounds || 0) + 1;
  execState.laps.push(Math.round((Date.now()-execState.lapStart)/1000)); execState.lapStart=Date.now();
  beep(660, .15);
  if(navigator.vibrate) navigator.vibrate(40);
  renderExecScreen();
}
function endRoundBlock(auto){
  if(!execState) return;
  const timer = execState.roundTimer;
  if(!timer) return;
  const item = execState.exercises[execState.currentIndex];
  if(!item) return;
  const rounds = execState.currentRounds || 0;
  if(!auto){
    if(!confirm('Завершить круговую?\nКругов выполнено: ' + rounds)) return;
  }
  recordRoundBlock(execState, item);
  stepExecExercise(auto ? timer.deadline : Date.now());
}
function recordRoundBlock(state, item){
  clearInterval(state.roundTimer.int);
  state.roundTimer = null;
  const rounds = state.currentRounds;
  state.currentRounds = 0;
  if(!rounds) return;
  for(const spec of item.blockExMapped || []){
    state.setLog.push({exId:spec.exId,name:spec.exName,reps:(Number(spec.reps)||0)*rounds,
      seconds:(Number(spec.time)||0)*rounds});
  }
  state.completed.push({exIdx:state.currentIndex,type:'rounds',rounds});
}
function execIsTimed(item){
  return item?.type !== 'rounds' && Number(item?.time) > 0 &&
    !isXValue(item.reps) && !isXValue(item.weight);
}

function setExecWakeLock(){
  const state = execState;
  if(!state?.timer.running || document.hidden || !navigator.wakeLock || state.wakeLock || state.wakePending) return;
  state.wakePending = true;
  navigator.wakeLock.request('screen').then(lock => {
    state.wakePending = false;
    if(execState !== state || !state.timer.running){ lock.release().catch(()=>{}); return; }
    state.wakeLock = lock;
    lock.addEventListener('release', () => {
      if(state.wakeLock === lock) state.wakeLock = null;
    });
  }).catch(()=>{state.wakePending = false;});
}

function releaseExecWakeLock(state){
  if(state.wakeLock) state.wakeLock.release().catch(()=>{});
  state.wakeLock = null;
}

document.addEventListener('visibilitychange', () => {
  if(!document.hidden && execState?.timer.running){
    tickExecTimer();
    setExecWakeLock();
  }
});

function execTimerCue(key){
  if(execState.timerOptions.sound) fujiCue(key);
  if(execState.timerOptions.vibration && navigator.vibrate){
    navigator.vibrate(key === 'workEnd' ? [70,55,70] : 70);
  }
}

function openExecTimerSettings(){
  if(execState?.phase !== 'idle') return;
  const state = execState;
  const current = state.exercises[state.currentIndex];
  const timed = execIsTimed(current);
  const set = (id, value) => { document.getElementById(id).value = value; };
  set('timerPrep', state.timerOptions.prep);
  document.getElementById('timedDosageSettings').hidden = !timed;
  document.getElementById('timerDosageScope').textContent = !timed ? '' : state.intervalCircuitLength ?
    ' Работа, отдых и подходы применятся ко всем предстоящим станциям.' :
    ' Работа, отдых и подходы меняются для текущего упражнения.';
  if(timed){
    set('timerWork', current.time);
    set('timerRest', Number(current.rest) || 0);
    set('timerSets', Number(current.sets) || 1);
  }
  for(const key of ['advance','sound','vibration']){
    document.getElementById('execTimer_'+key).checked = state.timerOptions[key];
  }
  set('timerMode', state.timerOptions.automatic ? 'automatic' : 'manual');
  openModal('m-exec-timer');
}

function saveExecTimerSettings(event){
  event.preventDefault();
  if(execState?.phase !== 'idle') return;
  const form = event.currentTarget;
  const value = id => document.getElementById(id).value;
  const current = execState.exercises[execState.currentIndex];
  const timed = execIsTimed(current);
  for(const input of form.querySelectorAll('#timedDosageSettings input')) input.disabled = !timed;
  if(!form.reportValidity()) return;
  const options = {prep:Number(value('timerPrep')), automatic:value('timerMode') === 'automatic'};
  for(const key of ['advance','sound','vibration']){
    options[key] = document.getElementById('execTimer_'+key).checked;
  }
  if(timed){
    const targets = execState.intervalCircuitLength ? execState.exercises.slice(execState.currentIndex) : [current];
    for(const item of targets){
      item.time = Number(value('timerWork'));
      const rest = Number(value('timerRest'));
      if(rest !== Number(item.rest || 0)) delete item.restPerSet;
      item.rest = rest;
      item.sets = Number(value('timerSets'));
    }
  }
  execState.timerOptions = options;
  if(!execState.intervalCircuitLength) store.set('execTimerOptions', options);
  closeModal('m-exec-timer');
  renderExecScreen();
}

function execStartWork(){
  const state = execState;
  if(!state) return;
  startWorkoutClock();
  if(state.timerOptions.sound) fujiUnlock();
  if(state.phase === 'idle' && state.timerOptions.prep > 0){
    startExecPhase('prep', state.timerOptions.prep);
  } else {
    beginExecWork();
  }
}

function beginExecWork(at = Date.now()){
  const item = execState.exercises[execState.currentIndex];
  startExecPhase('work', Number(item.time) || 0, at);
}

function stopExecClock(state){
  clearInterval(state.timer.int);
  state.timer.int = null;
  state.timer.running = false;
}

function commitExecWork(state, until = Date.now()){
  const timer = state.timer;
  if(state.phase === 'work' && timer.workStarted !== null){
    state.setWorkMs += Math.max(0, Math.min(until, timer.deadline || until) - timer.workStarted);
    timer.workStarted = null;
  }
}

function startExecPhase(phase, seconds, at = Date.now()){
  const state = execState;
  stopExecClock(state);
  state.phase = phase;
  const deadline = seconds > 0 ? at + seconds * 1000 : 0;
  state.timer = {
    remaining: deadline ? Math.max(0, Math.ceil((deadline - Date.now()) / 1000)) : 0,
    total:seconds, deadline, running:seconds > 0, int:null,
    workStarted:phase === 'work' ? at : null, paused:false
  };
  if(phase === 'work') execTimerCue('start');
  if(phase === 'rest') execTimerCue('rest');
  if(seconds > 0){
    state.timer.int = setInterval(tickExecTimer, 120);
    setExecWakeLock();
  }
  renderExecScreen();
}

function tickExecTimer(){
  const state = execState;
  if(!state?.timer.running) return;
  const timer = state.timer;
  const now = Date.now();
  timer.remaining = Math.max(0, Math.ceil((timer.deadline - now) / 1000));
  const display = document.querySelector('#execBody .exec-timer');
  if(display) display.textContent = fmt(timer.remaining);
  if(now < timer.deadline) return;
  const at = timer.deadline;
  commitExecWork(state, at);
  stopExecClock(state);
  const item = state.exercises[state.currentIndex];
  if(state.phase === 'prep') return beginExecWork(at);
  if(state.phase === 'rest'){
    if(state.timerOptions.automatic && execIsTimed(item)) return beginExecWork(at);
    execTimerCue('restEnd');
  }
  if(state.phase === 'work'){
    if(state.timerOptions.automatic && execIsTimed(item)) return execFinishSet(at);
    execTimerCue('workEnd');
  }
  releaseExecWakeLock(state);
  renderExecScreen();
}

function toggleExecTimer(){
  const state = execState;
  if(!state || state.finishingSet || state.summary) return;
  const timer = state.timer;
  const now = Date.now();
  if(timer.running && now >= timer.deadline) return tickExecTimer();
  if(!timer.running && !timer.paused && timer.workStarted === null) return;
  if(timer.paused){
    timer.paused = false;
    timer.deadline = timer.total > 0 ? now + timer.pauseMs : 0;
    timer.workStarted = state.phase === 'work' ? now : null;
    if(timer.total > 0){
      timer.running = true;
      timer.int = setInterval(tickExecTimer,120);
      setExecWakeLock();
    }
  } else {
    commitExecWork(state, now);
    timer.pauseMs = Math.max(0, timer.deadline - now);
    timer.remaining = Math.ceil(timer.pauseMs / 1000);
    timer.paused = true;
    stopExecClock(state);
    releaseExecWakeLock(state);
  }
  renderExecScreen();
}
/* ⚡ Спрашивает повторы/вес после каждого подхода через askPrompt */
async function execFinishSet(at = Date.now()){
  const state = execState;
  if(!state || state.phase !== 'work' || state.finishingSet || state.summary) return;
  const item = state.exercises[state.currentIndex];
  commitExecWork(state, at);
  stopExecClock(state);
  const totalSets = Number(item.sets) || 1;
  const set = state.currentSet;
  if(item.twoSides && state.currentSide === 1){
    state.currentSide = 2;
    continueExecAfterRest(Number(item.rest) || 0, at);
    return;
  }

  state.finishingSet = true;
  releaseExecWakeLock(state);
  let reps = state.du234Override?.reps ?? (Number(item.reps) || 0);
  let weight = state.du234Override?.weight ?? (Number(item.weight) || 0);
  try{
    if(isXValue(item.reps) && state.du234Override?.reps == null){
      const value = await askPrompt('Подход ' + set + ': сколько повторов' +
        (item.twoSides ? ' на одну сторону' : '') + ' сделали?', String(state.currentRepsPerSet[set - 2] ?? ''));
      if(value === null || execState !== state) return;
      reps = Number(value) || 0;
    }
    if(isXValue(item.weight) && state.du234Override?.weight == null){
      const value = await askPrompt('Подход ' + set + ': какой вес использовали? (кг)',
        String(state.currentWeightPerSet[set - 2] ?? ''));
      if(value === null || execState !== state) return;
      weight = Number(value) || 0;
    }
  } finally {
    state.finishingSet = false;
  }
  if(execState !== state) return;
  if(isXValue(item.reps) || isXValue(item.weight)) at = Date.now();
  state.currentRepsPerSet.push(reps);
  state.currentWeightPerSet.push(weight);
  const seconds = Math.round(state.setWorkMs / 1000);
  state.durationBySet.push(seconds);
  state.setLog.push({exId:item.exId, name:item.exName, reps:reps*(item.twoSides ? 2 : 1), seconds,weight,rpe:state.du234Override?.rpe ?? null});
  state.du234Override=null;
  state.setWorkMs = 0;

  if(set < totalSets){
    state.currentSet++;
    state.currentSide = 1;
    continueExecAfterRest(Number(item.restPerSet?.[set - 1] ?? item.rest) || 0, at);
    return;
  }

  state.completed.push({
    exIdx:state.currentIndex, sets:totalSets, repsPerSet:state.currentRepsPerSet,
    weightPerSet:state.currentWeightPerSet,
    time:Math.round(state.durationBySet.reduce((sum, seconds) => sum+seconds, 0) / totalSets / (item.twoSides ? 2 : 1)),
    seconds:state.durationBySet.reduce((sum, seconds) => sum+seconds, 0), twoSides:item.twoSides
  });
  const next = state.exercises[state.currentIndex + 1];
  const autoNext = state.timerOptions.automatic && state.timerOptions.advance &&
    execIsTimed(item) && execIsTimed(next);
  stepExecExercise(at);
  if(autoNext) continueExecAfterRest(Number(item.restPerSet?.[set - 1] ?? item.rest) || 0, at);
}

function continueExecAfterRest(seconds, at){
  if(seconds > 0) startExecPhase('rest', seconds, at);
  else beginExecWork(at);
}

function execSkipRest(){
  if(execState && ['rest','prep'].includes(execState.phase)) beginExecWork();
}

function stepExecExercise(at = Date.now()){
  const state = execState;
  state.currentIndex++;
  if(state.currentIndex >= state.exercises.length){ finishExecution(at); return; }
  state.currentRepsPerSet = [];
  state.currentWeightPerSet = [];
  state.durationBySet = [];
  state.setWorkMs = 0;
  state.currentSet = 1;
  state.currentSide = 1;
  state.phase = 'idle';
  state.timer = {remaining:0, total:0, running:false, int:null, workStarted:null};
  releaseExecWakeLock(state);
  renderExecScreen();
}

function execSkipExercise(){
  const state = execState;
  if(!state || state.finishingSet || !confirm('Пропустить упражнение?')) return;
  stopExecClock(state);
  recordPartialExercise(state);
  stepExecExercise();
}
function recordPartialExercise(state){
  const sets = state.currentRepsPerSet.length;
  if(!sets) return;
  const seconds = state.durationBySet.reduce((sum, value) => sum+value, 0);
  state.completed.push({exIdx:state.currentIndex,sets,repsPerSet:state.currentRepsPerSet,
    weightPerSet:state.currentWeightPerSet,time:Math.round(seconds/sets/(state.exercises[state.currentIndex].twoSides ? 2 : 1)),seconds});
}
function executionExerciseXp(result, item){
  if(result.type === 'rounds') return xpForOneRound(item) * (result.rounds || 0);
  const exercise = exercises.find(ex => ex.id === item.exId);
  if(!exercise) return 0;
  const sides = item.twoSides ? 2 : 1;
  const reps = result.repsPerSet || [];
  if(exercise.format === 'time' || (execIsTimed(item) && !reps.some(count => count > 0))){
    return xpFromTime(result.seconds ?? result.time * result.sets * sides);
  }
  if(exercise.format === 'weight'){
    return reps.reduce((xp, count, index) =>
      xp + xpFromWeight(result.weightPerSet?.[index] || 0, profile.weight || 70, count), 0) * sides;
  }
  return xpFromReps(reps.reduce((sum, count) => sum + count, 0) * sides);
}

function finishExecution(at = Date.now()){
  if(execState.summary) return;
  execState.summary = true;
  execState.elapsedSeconds = finishWorkoutClock(at);
  execTimerCue('workEnd');
  stopExecClock(execState);
  releaseExecWakeLock(execState);
  if(execState.timer.int) clearInterval(execState.timer.int);
  if(execState.roundTimer && execState.roundTimer.int) clearInterval(execState.roundTimer.int);
  const body = document.getElementById('execBody');
  const footer = document.getElementById('execFooter');
  const progressTxt = document.getElementById('execProgressTxt');
  const xp = Math.round(execState.completed.reduce((sum, result) =>
    sum + executionExerciseXp(result, execState.exercises[result.exIdx]), 0) * 100) / 100;
  if(progressTxt) progressTxt.textContent = '✓';
  body.innerHTML =
    '<div style="text-align:center;padding:40px 0">'+
      '<div style="font-size:64px;margin-bottom:16px">🎉</div>'+
      '<div style="font-size:22px;font-weight:900;margin-bottom:8px">Тренировка завершена!</div>'+
      '<div style="font-size:14px;color:var(--mut);margin-bottom:24px">Выполнено: '+execState.completed.length+' из '+execState.exercises.length+'</div>'+
      fujiSummary(fujiNormalResult())+
      '<div style="font-size:36px;font-weight:900;background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent">+'+xp+' XP</div>'+
    '</div>';
  footer.innerHTML =
    (execState.completed.length
      ? '<button class="btn btn-primary exec-finish" onclick="confirmFinishExecution('+xp+')">✓ Засчитать тренировку</button>'
      : '<p class="note">Нет завершённых подходов или кругов для записи.</p>')+
    '<button class="btn btn-full" style="margin-top:8px;padding:12px" onclick="closeExecScreen()">Отмена</button>';
}

function confirmFinishExecution(xp){
  if(!execState?.summary || execState.saved) return;
  const tr = execState.sessionPlan || trainings.find(t => t.id === execState.trainId);
  if(!tr || !execState.completed.length){ closeExecScreen(); return; }
  const dateKey = execState.dateKey;
  const date = localScheduleDate(dateKey);
  if(isTrainDone(date, tr)) return;
  const actualExs = execState.completed.map(c => {
    const tpl = execState.exercises[c.exIdx];
    if(tpl.type === 'rounds'){
      return {...tpl, blockEx:tpl.blockExMapped, actualRounds:c.rounds || 0, xpShare:executionExerciseXp(c, tpl)};
    }
    return {
      ...tpl,
      sets: c.sets || +tpl.sets || 1,
      xpShare: executionExerciseXp(c, tpl),
      repsPerSet: c.repsPerSet || null,
      weightPerSet: c.weightPerSet || null,
      reps: (c.repsPerSet && c.repsPerSet.length)
        ? (c.repsPerSet.reduce((s,r)=>s+r,0) / c.repsPerSet.length)
        : +tpl.reps || 0,
      weight: (c.weightPerSet && c.weightPerSet.length)
        ? c.weightPerSet[0]
        : +tpl.weight || 0,
      twoSides: !!tpl.twoSides,
      time: c.time ?? (Number(tpl.time) || 0)
    };
  });

  execState.saved = true;
  if(execState.sessionPlan && !trainings.some(plan => plan.id === tr.id)){
    trainings.push(tr);
    store.set('trainings', trainings);
  }
  fujiSaveResult({...fujiNormalResult(),calendarId:tr.id,calendarDate:isoDate(date)});
  setTrainDone(date, tr.id, true, xp, JSON.parse(JSON.stringify(actualExs)), execState.elapsedSeconds);
  addXp(xp, tr.name, {exercises:actualExs});
  const regularExs = actualExs.filter(e => e.type !== 'rounds');
  const newPRs = checkNewPRs(regularExs, dateKey);
  if(newPRs.length > 0){
    setTimeout(() => {
      newPRs.forEach((pr, i) => setTimeout(() => prFly(pr.exName, pr.display), i * 800));
    }, 300);
  }
  renderWeek(); renderMonth(); renderTrainings(); renderStats();
  closeExecScreen();
  execState = null;
  toast('Тренировка засчитана: +'+xp+' XP');
}

function fmt(s){ return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0'); }
let audioCtx = null;
const fujiVoiceData = {"start": "", "rest": "", "workEnd": "", "restEnd": "", "lap": "", "finish": ""};
const fujiVoiceBuffers = {}; let fujiVoiceSource = null; let fujiSoundToken=0;
function fujiUnlock(){try{if(!audioCtx)audioCtx=new (window.AudioContext||window.webkitAudioContext)(); if(audioCtx.state==='suspended')audioCtx.resume().catch(()=>{}); for(const [key,data] of Object.entries(fujiVoiceData)){if(!fujiVoiceBuffers[key]){const bytes=Uint8Array.from(atob(data),c=>c.charCodeAt(0));fujiVoiceBuffers[key]=audioCtx.decodeAudioData(bytes.buffer).catch(()=>null);}}}catch(e){}}
document.addEventListener('pointerdown',fujiUnlock,{passive:true});
document.addEventListener('keydown',fujiUnlock);
let duCueNodes=[];
function duStopCues(){fujiSoundToken++;for(const node of duCueNodes){try{node.stop();}catch(e){}}duCueNodes=[];if(fujiVoiceSource){try{fujiVoiceSource.stop();}catch(e){}fujiVoiceSource=null;}}
function fujiCue(key){try{fujiUnlock();if(!audioCtx)return;duStopCues();const token=fujiSoundToken;const notes={start:[880,1320,1760],rest:[880,440],workEnd:[1100,550],restEnd:[660,990,1485],lap:[990,1320],finish:[660,880,1100,1320]}[key]||[880];const t=audioCtx.currentTime;const compressor=audioCtx.createDynamicsCompressor();compressor.threshold.value=-18;compressor.ratio.value=4;compressor.connect(audioCtx.destination);notes.forEach((f,i)=>{const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='triangle';o.frequency.value=f;const a=t+i*.20;g.gain.setValueAtTime(.001,a);g.gain.linearRampToValueAtTime(.85,a+.012);g.gain.setValueAtTime(.65,a+.12);g.gain.exponentialRampToValueAtTime(.001,a+.18);o.connect(g);g.connect(compressor);o.start(a);o.stop(a+.19);duCueNodes.push(o);});Promise.resolve(fujiVoiceBuffers[key]).then(buffer=>{if(token!==fujiSoundToken||!buffer)return;const source=audioCtx.createBufferSource(),g=audioCtx.createGain();source.buffer=buffer;g.gain.value=1.7;source.connect(g);g.connect(compressor);fujiVoiceSource=source;source.start(Math.max(audioCtx.currentTime,t+notes.length*.20+.04));});}catch(e){}}
function beep(freq,dur){fujiCue(freq===950?'start':freq===660?'lap':freq===1100?'restEnd':'workEnd');}
