async function shareDB(){
  const data = JSON.stringify(buildDB(), null, 2);
  const file = new File([data], 'du.json', {type:'application/json'});
  if(navigator.canShare && navigator.canShare({files:[file]})){
    try { await navigator.share({files:[file], title:'База ДУ'}); toast('Отправлено'); }
    catch(e){ if(e.name !== 'AbortError') toast('Ошибка'); }
  } else if(navigator.share){
    try { await navigator.share({title:'База ДУ', text: exercises.length+' упражнений'}); toast('Отправлено'); }
    catch(e){ if(e.name !== 'AbortError') toast('Ошибка'); }
  } else toast('Share недоступен');
}
async function copyDB(){
  const data = JSON.stringify(buildDB());
  try { await navigator.clipboard.writeText(data); toast('Скопировано'); }
  catch(e){ toast('Не удалось'); }
}
