/* ==================== МИГРАЦИЯ ЗОН ==================== */
function migrateZonesV20(){
  if(!Array.isArray(zones)) return false;
  let changed = false;

  const obsolete = ['abs_upper', 'abs_lower'];
  const beforeLen = zones.length;
  zones = zones.filter(z => !obsolete.includes(z.id));
  if(zones.length !== beforeLen){
    let exChanged = false;
    exercises.forEach(e => {
      if(!Array.isArray(e.zones)) return;
      const mapped = e.zones.map(z => obsolete.includes(z) ? 'abs' : z);
      const uniq = [...new Set(mapped)];
      if(uniq.length !== e.zones.length || uniq.some((v,i) => v !== e.zones[i])){
        e.zones = uniq; exChanged = true;
      }
    });
    if(exChanged) store.set('exercises', exercises);
    changed = true;
  }

  const zoneMap = {}; zones.forEach(z => { zoneMap[z.id] = z; });
  const addZones = [
    {id:'shoulders_bi', name:'Бицепс', emoji:'💪', parent:'shoulders'},
    {id:'glutes_min', name:'Малая ягодичная', emoji:'🍑', parent:'glutes'},
    {id:'hips_abd', name:'Отводящие', emoji:'🦵', parent:'hips'},
    {id:'abs_rectus', name:'Прямая', emoji:'🔥', parent:'abs'},
    {id:'abs_transv', name:'Поперечная', emoji:'🔥', parent:'abs'},
    {id:'calves_gastr', name:'Икра', emoji:'🦿', parent:'calves'},
    {id:'calves_soleus', name:'Камбала', emoji:'🦿', parent:'calves'},
    {id:'calves_tib', name:'Берцовые', emoji:'🦿', parent:'calves'},
    {id:'face', name:'Лицо', emoji:'😊', isMain:true},
  ];
  addZones.forEach(nz => {
    if(!zoneMap[nz.id]){ zones.push(nz); changed = true; }
  });

  const calvesZone = zones.find(z => z.id === 'calves');
  if(calvesZone && calvesZone.name !== 'Голень'){ calvesZone.name = 'Голень'; changed = true; }

  if(changed) store.set('zones', zones);
  return changed;
}

