function switchStatTab(btn){
  statActiveTab = btn.dataset.tab;
  store.set('statActiveTab', statActiveTab);
  applyStatTab();
  if(statActiveTab === 'progress') setTimeout(() => renderProgressChart(), 60);
  if(statActiveTab === 'char') setTimeout(() => renderCharacter(), 60);
}
function applyStatTab(){
  const groups = {char:'char',progress:'results',summary:'results',gears:'development',zones:'development',
    skills:'development',log:'history',history:'history'};
  const tab = Object.hasOwn(groups,statActiveTab) ? statActiveTab : 'char';
  const group = groups[tab];
  document.getElementById('statResultsTabs').hidden = group !== 'results';
  document.getElementById('statDevelopmentTabs').hidden = group !== 'development';
  document.getElementById('statHistoryTabs').hidden = group !== 'history';
  document.querySelectorAll('#v-stat button[data-tab]').forEach(button => {
    const active = button.dataset.statGroup ? button.dataset.statGroup === group : button.dataset.tab === tab;
    button.classList.toggle('on',active);
    button.setAttribute('aria-pressed',String(active));
  });
  document.querySelectorAll('#v-stat .stat-panel').forEach(panel => panel.classList.toggle('on',panel.dataset.panel === tab));
}
