function fujiLaunch(mode){const c=complexes.find(x=>x.id===fujiSelected);if(!c||!c.exercises.length)return;let target=0;if(mode!=='normal'){target=Number(document.getElementById('fujiTarget').value);if(!Number.isInteger(target)||target<1||target>10000){toast('Укажи количество от 1 до 10000');return;}}closeModal('m-fuji-detail');if(mode==='normal'){const id='fuji_session_'+uid();const session={id,name:c.name,time:'18:00',days:[TODAY.getDay()],startDate:isoDate(TODAY),endDate:isoDate(TODAY),exercises:c.roundMode?[{type:'rounds',name:c.name,time:(c.roundTime||20)*60,blockEx:c.exercises}]:c.exercises};selectedDate=new Date(TODAY);startCalendarTraining(id,session);return;}fujiRun={id:c.id,name:c.name,mode,target,count:0,index:0,started:Date.now(),lapStart:Date.now(),laps:[],exerciseStats:{},roundMarked:[],exercises:c.exercises};startWorkoutClock();beep(950,.2);document.getElementById('execScreen').classList.add('on');document.getElementById('execTitle').textContent=c.name;fujiDrawRun();fujiTick=setInterval(()=>{const e=document.getElementById('fujiClock');if(e&&fujiRun)e.textContent=fmt(Math.floor((Date.now()-fujiRun.started)/1000));},250);}
