function fujiRecord(r,a,n){const k=a.exId||a.name;const e=exercises.find(x=>x.id===a.exId);const x=r.exerciseStats[k]||(r.exerciseStats[k]={name:e?.name||a.name||'Упражнение',reps:0,sets:0});if(n!=null)x.reps+=n;else x.unknown=true;x.sets++;}
function fujiNext(){if(fujiRun.mode==='rounds'){const r=fujiRun;if(!r.roundMarked.includes(r.index)){const a=r.exercises[r.index];fujiRecord(r,a,a.reps? a.reps*(a.sets||1):null);r.roundMarked.push(r.index);}}fujiRun.index=(fujiRun.index+1)%fujiRun.exercises.length;fujiDrawRun();}
function fujiAdd(n){const r=fujiRun;if(!r)return;if(r.mode==='reps')fujiRecord(r,r.exercises[r.index],Math.min(n,r.target-r.count));else {r.exercises.forEach((a,i)=>{if(!r.roundMarked.includes(i))fujiRecord(r,a,a.reps?a.reps*(a.sets||1):null);});r.roundMarked=[];}r.count=Math.min(r.target,r.count+n);if(r.mode==='rounds'){r.laps.push(Math.round((Date.now()-r.lapStart)/1000));r.lapStart=Date.now();r.index=0;beep(660,.15);}if(r.count>=r.target)fujiFinish();else fujiDrawRun();}
