function canRunAmrap(plan){
  return plan.exercises.length > 0 && plan.exercises.every(item =>
    Number.isInteger(item.reps) && item.reps > 0 && (item.sets || 1) === 1 && !item.time && !item.rest);
}

const showComplexDetail = fujiDetail;
fujiDetail = function(id){
  showComplexDetail(id);
  const plan = complexes.find(item => item.id === id);
  const amrap = plan && plan.roundMode && amrapTemplates.some(item => item.id === id) && canRunAmrap(plan);
  document.querySelector('#m-fuji-detail .btn-primary').textContent = amrap
    ? '▶ Старт · ' + (plan.roundTime || 20) + ' мин'
    : '▶ Обычная тренировка';
  if(!amrap) return;
  const video = id === kettlebellComplex.id
    ? '<p><a href="' + kettlebellVideo + '" target="_blank" rel="noopener noreferrer">Смотреть оригинал · Adrian Goldstein</a></p>'
    : '';
  document.getElementById('fujiDetailList').insertAdjacentHTML('afterbegin',
    '<div class="card"><b>AMRAP · ' + fmt((plan.roundTime || 20) * 60) + '</b>' +
    '<p>Выполни максимум полных кругов. Отдыхай по необходимости, таймер продолжает идти. ' +
    'Приложение запишет полные круги и повторения по каждому движению.</p>' + video + '</div>');
};

const launchComplex = fujiLaunch;
fujiLaunch = function(mode){
  const plan = complexes.find(item => item.id === fujiSelected);
  if(mode !== 'normal' || !plan?.roundMode ||
      !amrapTemplates.some(item => item.id === plan.id) || !canRunAmrap(plan)){
    return launchComplex(mode);
  }
  closeModal('m-fuji-detail');
  startAmrap(plan, (plan.roundTime || 20) * 60);
};

function startAmrap(plan, limit, calendarEntry = null){
  if(amrapRun || execState) return;
  const options = {...{prep:10,sound:true}, ...store.get('execTimerOptions', {})};
  if(options.sound) fujiUnlock();
  startWorkoutClock();
  const start = Date.now() + options.prep * 1000;
  amrapRun = {
    id:plan.id, name:plan.name, exercises:plan.exercises,
    names:plan.exercises.map(item => exercises.find(ex => ex.id === item.exId)?.name || item.name || 'Упражнение'),
    repsPerRound:plan.exercises.reduce((sum,item) => sum + item.reps, 0),
    limit, start, lapStart:start, index:0, partial:0, reps:0, rounds:0, laps:[],
    ready:false, pausedAt:null, calendarEntry, sound:options.sound,
    byExercise:plan.exercises.map(() => 0)
  };
  document.getElementById('execScreen').classList.add('on');
  document.getElementById('execTitle').textContent = plan.name;
  renderAmrap();
  amrapTimer = setInterval(updateAmrap, 200);
}

function updateAmrap(){
  if(!amrapRun) return;
  const r = amrapRun;
  const now = r.pausedAt ?? Date.now();
  if(!r.ready && now >= r.start){
    r.ready = true;
    if(r.sound) fujiCue('start');
    renderAmrap();
    return;
  }
  const deadline = r.ready ? r.start + r.limit * 1000 : r.start;
  const left = Math.max(0, Math.ceil((deadline - now) / 1000));
  document.getElementById('amrapClock').textContent = fmt(left);
  document.getElementById('amrapBar').style.width = (r.ready ? left / r.limit * 100 : 0) + '%';
  if(r.ready && left === 0) finishAmrap(deadline);
}

function toggleAmrapPause(){
  if(!amrapRun) return;
  const r = amrapRun;
  if(r.pausedAt === null){
    r.pausedAt = Date.now();
  } else {
    const paused = Date.now() - r.pausedAt;
    r.start += paused;
    r.lapStart += paused;
    r.pausedAt = null;
  }
  renderAmrap();
}
function renderAmrap(){
  const r = amrapRun;
  const item = r.exercises[r.index];
  const exercise = exercises.find(ex => ex.id === item.exId);
  const gallery = fujiGuideHtml(exercise,true);
  const media = gallery || (exercise?.media?.some(entry => entry.type === 'image') ? fujiPic(exercise) : '');
  const description = gallery ? '' : exercise?.desc || item.note;
  document.getElementById('execProgressTxt').textContent = (r.index + 1) + '/' + r.exercises.length + ' · ' + r.rounds + ' кр.';
  document.getElementById('execBody').innerHTML =
    '<div class="exec-focus"><div class="exec-ex-name">' + escapeHtml(r.names[r.index]) + '</div>' +
    '<div class="exec-phase">'+ (r.pausedAt !== null ? 'Пауза' : r.ready ? 'AMRAP' : 'Подготовка') +'</div>' +
    '<div class="exec-timer" id="amrapClock"></div><div class="cindy-progress"><i id="amrapBar"></i></div>' +
    (r.ready ? '<b>' + r.partial + ' / ' + item.reps + ' повторений</b>' : '') + media +
    (description ? '<p class="fuji-note">' + escapeHtml(description) + '</p>' : '') + '</div>';
  const active = r.ready && r.pausedAt === null;
  document.getElementById('execFooter').innerHTML =
    (active ? '<div class="btn-row"><button class="btn" onclick="addAmrapReps(1)">+1 повтор</button>' +
      '<button class="btn btn-primary" onclick="addAmrapReps()">Упражнение готово</button></div>' : '') +
    '<div class="exec-controls"><button class="btn" onclick="toggleAmrapPause()">' +
      (r.pausedAt === null ? 'Пауза' : 'Продолжить') + '</button>' +
      '<button class="btn" onclick="confirmAmrapFinish()">Завершить</button></div>';
  updateAmrap();
}

function addAmrapReps(reps){
  if(!amrapRun?.ready || amrapRun.pausedAt !== null) return;
  const r = amrapRun;
  const now = Date.now();
  if(now >= r.start + r.limit * 1000){
    finishAmrap(r.start + r.limit * 1000);
    return;
  }
  const remaining = r.exercises[r.index].reps - r.partial;
  const added = Math.min(reps ?? remaining, remaining);
  r.byExercise[r.index] += added;
  r.reps += added;
  r.partial += added;
  if(added === remaining){
    r.partial = 0;
    r.index++;
    if(r.index === r.exercises.length){
      r.index = 0;
      r.rounds++;
      r.laps.push(Math.round((now - r.lapStart) / 1000));
      r.lapStart = now;
      if(r.sound) fujiCue('lap');
    }
  }
  renderAmrap();
}

function confirmAmrapFinish(){
  if(amrapRun && confirm('Завершить тренировку и сохранить результат?')) finishAmrap();
}

function finishAmrap(at = Date.now()){
  if(!amrapRun) return;
  const r = amrapRun;
  clearInterval(amrapTimer);
  amrapRun = null;
  const elapsedSeconds = finishWorkoutClock(at);
  const result = {
    id:r.id, name:r.name, mode:'amrap', target:r.limit, count:r.reps, reps:r.reps,
    rounds:r.rounds, elapsedSeconds, seconds:Math.max(0, Math.min(r.limit, Math.round(((r.pausedAt ?? at) - r.start) / 1000))),
    laps:r.laps, date:new Date().toISOString(),
    exerciseStats:r.names.map((name,i) => ({name,reps:r.byExercise[i]}))
  };
  if(r.calendarEntry){result.calendarId=r.calendarEntry.id;result.calendarDate=r.calendarEntry.date;}
  if(r.sound && r.ready) fujiCue('finish');
  duPendingSave = () => {
  if(r.ready) fujiSaveResult(result);
  if(r.reps > 0){
    const completed = r.exercises.flatMap((item, index) => r.byExercise[index] > 0 ? [{
      ...item, sets:1, reps:r.byExercise[index], xpShare:xpFromReps(r.byExercise[index])
    }] : []);
    const xp = xpFromReps(r.reps);
    if(r.calendarEntry){
      const {id, date} = r.calendarEntry;
      setTrainDone(localScheduleDate(date), id, true, xp, completed, elapsedSeconds);
    }
    addXp(xp, r.name, {exercises:completed});
    renderWeek(); renderMonth(); renderTrainings(); renderStats();
  }
  };
  renderWorkoutClock();
  document.getElementById('execBody').innerHTML =
    '<div class="card"><h2>Тренировка завершена</h2>' + fujiSummary(result) + '<p>Результат: ' +
    r.rounds + ' кр. + ' + (r.reps - r.rounds * r.repsPerRound) + ' повт.</p></div>';
  document.getElementById('execFooter').innerHTML =
    '<button class="btn btn-primary btn-full" onclick="duSavePending()">Засчитать тренировку</button><button class="btn btn-full" onclick="cancelWorkout()">Отменить без XP</button>';
}

const closeTraining = closeExecScreen;
closeExecScreen = function(){
  if(amrapRun) return confirmAmrapFinish();
  return closeTraining();
};

const startCalendarTraining = startTrainExecution;
startTrainExecution = function(id){
  const training = trainings.find(item => item.id === id);
  if(training && isTrainScheduled(training, selectedDate) && isoDate(selectedDate) <= isoDate(TODAY)){
    const items = getEffectiveTrain(training, selectedDate).exercises || [];
    const block = items[0];
    if(items.length === 1 && block.type === 'rounds' && block.time > 0 && block.blockEx){
      const template = amrapTemplates.find(plan => plan.exercises.length === block.blockEx.length &&
        plan.exercises.every((item,i) => item.exId === block.blockEx[i].exId));
      const plan = template && {...template, exercises:block.blockEx};
      if(plan && canRunAmrap(plan) && !isTrainDone(selectedDate, training)){
        return startAmrap({...plan, name:training.name}, block.time, {id, date:isoDate(selectedDate)});
      }
    }
  }
  return startCalendarTraining(id);
};

