let exerciseLibrary = null;
let exerciseLibraryMessage = 'Выбери файл DU_Exercise_Library.json. База содержит упражнения, комплексы и изображения.';
let exerciseLibraryBooting = true;
const EXERCISE_DB_FILENAME = 'DU_Exercise_Library.json';

function validateExerciseLibrary(value){
  if(value?.schema!=='du-exercise-library' || !Array.isArray(value.exercises) || !Array.isArray(value.complexes) ||
      !value.guides || !value.guideIds || !value.guideNames || !value.stock) throw Error('Это не база упражнений ДУ');
  const ids=new Set();
  for(const exercise of value.exercises){
    if(!exercise || typeof exercise.id!=='string' || typeof exercise.name!=='string' || !exercise.name.trim() ||
        ids.has(exercise.id) || !Array.isArray(exercise.media)) throw Error('Некорректная карточка упражнения');
    ids.add(exercise.id);
    for(const item of exercise.media){
      if(!['image','video'].includes(item.type) || typeof item.data!=='string' ||
         !new RegExp('^data:'+item.type+'/[a-zA-Z0-9.+-]+;base64,[a-zA-Z0-9+/=]+$').test(item.data)) throw Error('Некорректное медиа упражнения');
    }
  }
  for(const complex of value.complexes){
    if(!complex || typeof complex.id!=='string' || typeof complex.name!=='string' || !Array.isArray(complex.exercises)) throw Error('Некорректный комплекс');
  }
  for(const guide of Object.values(value.guides)){
    if(!Array.isArray(guide) || typeof guide[0]!=='string' || !Array.isArray(guide[2]) ||
        !(guide[1]===null || typeof guide[1]==='string' && (!guide[1] || /^https:\/\/[^"'<>\s]+$/.test(guide[1])))) throw Error('Некорректная техника упражнения');
    if(guide[2].length>16) throw Error('Слишком много кадров в упражнении');
    for(const frame of guide[2]){
      if(!Array.isArray(frame) || typeof frame[0]!=='string' || typeof frame[1]!=='string' ||
          !/^data:image\/(?:webp|png|jpeg);base64,[a-zA-Z0-9+/=]+$/.test(frame[1])) throw Error('Некорректный кадр техники');
    }
  }
  for(const map of [value.guideIds,value.guideNames]){
    if(typeof map!=='object' || Object.values(map).some(key=>typeof key!=='string'||!Object.hasOwn(value.guides,key))) throw Error('Неверная ссылка на технику');
  }
  return value;
}

function withExerciseDatabase(action){
  return new Promise((resolve,reject)=>{
    if(!window.indexedDB){reject(Error('Сохранение базы в этом браузере недоступно'));return;}
    const request=indexedDB.open('du-exercise-library',1);
    request.onupgradeneeded=()=>request.result.createObjectStore('libraries');
    request.onerror=()=>reject(request.error);
    request.onblocked=()=>reject(Error('Закрой другую открытую версию приложения'));
    request.onsuccess=()=>{
      const db=request.result;
      let transaction;
      try{
        transaction=db.transaction('libraries','readwrite');
        const result=action(transaction.objectStore('libraries'));
        transaction.oncomplete=()=>{const value=result.result;db.close();resolve(value);};
        transaction.onerror=()=>{db.close();reject(transaction.error);};
        transaction.onabort=()=>{db.close();reject(transaction.error || Error('Сохранение отменено'));};
      }catch(error){db.close();reject(error);}
    };
  });
}

function duFilteredSeed(value){
  if(!store.get('duCleanLibraryV1',false))return value;
  return {...value,
    exercises:(value.exercises||[]).filter(e=>DU_CLEAN_EX_IDS.has(e.id)),
    complexes:(value.complexes||[]).filter(c=>DU_CLEAN_COMP_IDS.has(c.id))};
}
function installLibrarySeed(){
  if(!exerciseLibrary) return;
  exerciseLibrary=duFilteredSeed(exerciseLibrary);
  const aliases=new Map();
  let exChanged=false,compChanged=false;
  for(const seed of exerciseLibrary.exercises){
    const existing=exercises.find(ex=>ex.id===seed.id) || (seed.id.startsWith('base_') ? exercises.find(ex=>ex.name===seed.name) : null);
    if(existing){
      aliases.set(seed.id,existing.id);
      // Update atlas media for existing exercises while retaining user-added photos/videos.
      if(exerciseLibrary.mascot==='davinci' && Array.isArray(seed.media) && seed.media.length){
        const oldAtlas=(existing.media||[]).filter(m=>m && m.duAtlas===true);
        const personal=(existing.media||[]).filter(m=>m && m.duAtlas!==true && !isLegacyFujiImage(m,existing.id));
        const incoming=seed.media.filter(m=>m && m.type==='image' && typeof m.data==='string')
          .map(m=>({...structuredClone(m),duAtlas:true}));
        // Do not replace unrelated user media or erase the original technique.
        const next=[...personal,...incoming];
        if(incoming.length && (oldAtlas.length!==incoming.length ||
          oldAtlas.some((m,i)=>m.data!==incoming[i].data) ||
          (existing.media||[]).length!==next.length)){
          existing.media=next;exChanged=true;
        }
      }
      continue;
    }
    exercises.push({...structuredClone(seed),media:exerciseLibrary.mascot==='davinci'?structuredClone(seed.media).map(m=>({...m,duAtlas:true})):[]});
    aliases.set(seed.id,seed.id);
    exChanged=true;
  }
  for(const seed of exerciseLibrary.complexes){
    if(complexes.some(item=>item.id===seed.id)) continue;
    const copy=structuredClone(seed);
    for(const item of copy.exercises) item.exId=aliases.get(item.exId)||item.exId;
    complexes.push(copy);
    compChanged=true;
  }
  // Old bundled illustrations are replaced by the library galleries.
  for(const exercise of exercises){
    const cleaned=(exercise.media||[]).filter(item=>!isLegacyFujiImage(item,exercise.id));
    if(cleaned.length!==(exercise.media||[]).length){exercise.media=cleaned;exChanged=true;}
  }
  if(exChanged) store.set('exercises',exercises);
  if(compChanged) store.set('complexes',complexes);
}

function applyExerciseLibrary(value){
  value=duFilteredSeed(value);
  exerciseLibrary=value;
  fujiGuides=Object.fromEntries(Object.entries(value.guides).map(([key,guide])=>[key,[guide[0],guide[1],value.mascot==='davinci'?guide[2]:[]]]));
  fujiGuideIds=value.guideIds;
  fujiGuideNames=value.guideNames;
  fujiStockDescription=value.stock;
  installLibrarySeed();
  exerciseLibraryBooting=false;
  renderAll();
  if(document.getElementById('m-fuji-detail')?.classList.contains('on') && fujiSelected) fujiDetail(fujiSelected);
  if(document.getElementById('m-ex')?.classList.contains('on') && editingExId){
    document.getElementById('exTeachingGuide').innerHTML=fujiGuideHtml(exercises.find(ex=>ex.id===editingExId));
  }
}

function renderExerciseLibraryStatus(){
  const status=document.getElementById('exerciseLibraryStatus');
  if(status) status.textContent=exerciseLibraryMessage;
  const notice=document.getElementById('exerciseLibraryNotice');
  if(notice) notice.hidden=!!exerciseLibrary;
  const helper=document.getElementById('exerciseLibraryHint');
  if(helper) helper.textContent=exerciseLibraryBooting?'Загружаю базу упражнений…':exerciseLibraryMessage;
}

async function bootExerciseLibrary(){
  let cached=null;
  try{cached=await withExerciseDatabase(store=>store.get('current'));}catch(error){console.info(error.message);}
  if(cached){
    try{
      validateExerciseLibrary(cached);
      exerciseLibraryMessage='База сохранена в браузере · '+cached.exercises.length+' упражнений';
      applyExerciseLibrary(cached);
    }catch(error){console.info(error.message);}
  }
  if(location.protocol==='http:' || location.protocol==='https:'){
    try{
      const response=await fetch(EXERCISE_DB_FILENAME,{cache:'no-cache'});
      if(!response.ok) throw Error('Файл базы не найден');
      const value=validateExerciseLibrary(await response.json());
      await acceptExerciseLibrary(value);
    }catch(error){if(!cached)console.info(error.message);}
  }
  exerciseLibraryBooting=false;
  renderExerciseLibraryStatus();
}

async function acceptExerciseLibrary(value){
  let persistent=false;
  try{
    await withExerciseDatabase(store=>store.put(value,'current'));
    persistent=true;
  }catch(error){console.info(error.message);}
  exerciseLibraryMessage=persistent
    ? 'База сохранена в браузере · '+value.exercises.length+' упражнений'
    : 'База загружена на этот сеанс. При следующем открытии выбери файл повторно.';
  applyExerciseLibrary(value);
  renderExerciseLibraryStatus();
}

async function chooseExerciseLibrary(input){
  const file=input.files?.[0];
  if(!file) return;
  try{
    const value=validateExerciseLibrary(JSON.parse(await file.text()));
    await acceptExerciseLibrary(value);
    toast('База упражнений подключена');
  }catch(error){toast(error.message || 'Не удалось прочитать базу');}
  finally{input.value='';}
}

function exportExerciseLibrary(){
  if(!exerciseLibrary){toast('Сначала подключи базу упражнений');return;}
  const value={...exerciseLibrary,updated:new Date().toISOString(),exercises,complexes,
    guides:fujiGuides,guideIds:fujiGuideIds,guideNames:fujiGuideNames,stock:fujiStockDescription};
  const data=new Blob([JSON.stringify(value)],{type:'application/json'});
  const link=document.createElement('a');
  link.href=URL.createObjectURL(data);link.download=EXERCISE_DB_FILENAME;
  link.click();
  setTimeout(()=>URL.revokeObjectURL(link.href),1000);
}

function duDay(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function duNormalize(x){const o={stepsGoal:8000,sleepGoal:8,days:{},demo:false};if(!x||typeof x!=='object')return o; o.stepsGoal=Math.min(50000,Math.max(100,Number(x.stepsGoal)||8000));o.sleepGoal=Math.min(12,Math.max(1,Number(x.sleepGoal)||8));o.demo=x.demo===true;for(const [k,v] of Object.entries(x.days||{})){if(!/^\d{4}-\d{2}-\d{2}$/.test(k)||!v)continue;o.days[k]={steps:Math.max(0,Math.min(100000,Number(v.steps)||0)),sleep:Math.max(0,Math.min(24,Number(v.sleep)||0)),stepGoal:Math.max(100,Number(v.stepGoal)||o.stepsGoal),sleepGoal:Math.max(1,Number(v.sleepGoal)||o.sleepGoal),stepAward:v.stepAward===true,sleepAward:v.sleepAward===true,source:v.source==='demo'?'demo':v.source==='import'?'import':'manual'};}return o;}
function duData(){return duNormalize(store.get('duHealth',null));}
function duMetric(label,val,goal,unit){return '<div class="du-metric"><small>'+label+'</small><b>'+val+' '+unit+'</b><div class="du-meter"><i style="width:'+Math.min(100,val/goal*100)+'%"></i></div><small>Цель: '+goal+' '+unit+'</small></div>';}
function duRender(){const h=duData(),d=h.days[duDay()]||{};const el=document.getElementById('duHealthSummary');if(el)el.innerHTML='<div class="du-health-grid">'+duMetric('Шаги',d.steps||0,d.stepGoal||h.stepsGoal,'')+duMetric('Сон',d.sleep||0,d.sleepGoal||h.sleepGoal,'ч')+'</div><small>'+ (d.source==='demo'?'ДЕМО · вымышленные данные':(d.source==='import'?'Импорт JSON · часы не подключены':'Ручной ввод · часы не подключены'))+'</small>';}
function duOpen(){let el=document.getElementById('duSheet');if(!el){el=document.createElement('section');el.id='duSheet';el.className='du-sheet';document.body.appendChild(el);}el.hidden=false;const h=duData(),d=h.days[duDay()]||{};el.innerHTML=`<button class="btn" onclick="document.getElementById('duSheet').hidden=true">← Назад</button><h2>Активность и сон</h2><p>${h.demo?'Демонстрационные данные — не реальные измерения':'Ручной ввод. Синхронизация часов пока недоступна.'}</p><div class="card"><h3>Мои нормативы</h3><label>Шагов в день</label><input id="duSG" type="number" min="100" max="50000" value="${h.stepsGoal}"><label>Часов сна</label><input id="duHG" type="number" min="1" max="12" step="0.25" value="${h.sleepGoal}"><button class="btn btn-primary btn-full" onclick="duGoals()">Сохранить цели</button><small>Новые цели действуют сегодня для ещё не полученных наград и в будущие дни. +1 XP за шаги и +1 XP за сон, не более одного раза за день.</small></div><div class="card"><h3>Сегодня</h3><label>Шаги</label><input id="duSteps" type="number" min="0" max="100000" value="${d.source==='demo'?0:(d.steps||0)}"><label>Сон, часы</label><input id="duSleep" type="number" min="0" max="24" step="0.25" value="${d.source==='demo'?0:(d.sleep||0)}"><button class="btn btn-primary btn-full" onclick="duSaveDay()">Записать результат</button><small>Цели на сегодня: ${d.stepGoal||h.stepsGoal} шагов · ${d.sleepGoal||h.sleepGoal} ч. ${d.stepAward?'Шаги ✓ ':''}${d.sleepAward?'Сон ✓':''}</small></div><div class="card"><h3>История</h3><label>Период</label><select id="duPeriod" onchange="duHistory()"><option value="7">7 дней</option><option value="30">30 дней</option></select><div id="duHist"></div></div><div class="card"><h3>Источники данных</h3><p>Apple Health / Health Connect / API часов — требуется отдельная интеграция. Сейчас доступен ручной ввод; часы не подключены.</p><button class="btn btn-full" onclick="duDemo()">${h.demo?'Очистить демоданные':'Заполнить демоданными'}</button></div>`;duHistory();}
function duGoals(){const h=duData(),a=document.getElementById('duSG'),b=document.getElementById('duHG');if(!a.reportValidity()||!b.reportValidity()||!a.value||!b.value)return;h.stepsGoal=Number(a.value);h.sleepGoal=Number(b.value);const d=h.days[duDay()];if(d){if(!d.stepAward)d.stepGoal=h.stepsGoal;if(!d.sleepAward)d.sleepGoal=h.sleepGoal;}store.set('duHealth',h);duRender();duOpen();}
function duSaveDay(){const h=duData(),a=document.getElementById('duSteps'),b=document.getElementById('duSleep');if(!a.reportValidity()||!b.reportValidity()||!a.value||!b.value)return;const k=duDay(),d=h.days[k]||{stepGoal:h.stepsGoal,sleepGoal:h.sleepGoal,stepAward:false,sleepAward:false};if(d.source==='demo'){d.stepAward=false;d.sleepAward=false;d.stepGoal=h.stepsGoal;d.sleepGoal=h.sleepGoal;}d.steps=Number(a.value);d.sleep=Number(b.value);d.source='manual';let plus=0;if(d.steps>=d.stepGoal&&!d.stepAward){d.stepAward=true;plus++;}if(d.sleep>=d.sleepGoal&&!d.sleepAward){d.sleepAward=true;plus++;}h.days[k]=d;store.set('duHealth',h);if(plus)addXp(plus,'Активность и сон');duRender();duOpen();}
function duHistory(){const h=duData(),n=Number(document.getElementById('duPeriod').value),el=document.getElementById('duHist');let html='',sum=0,sl=0,count=0;for(let i=0;i<n;i++){const t=new Date();t.setDate(t.getDate()-i);const k=t.getFullYear()+'-'+String(t.getMonth()+1).padStart(2,'0')+'-'+String(t.getDate()).padStart(2,'0');const d=h.days[k];if(!d)continue;sum+=d.steps;sl+=d.sleep;count++;html+='<div class="du-hrow"><span>'+k.slice(5)+(d.source==='demo'?' · демо':'')+'</span><span>'+d.steps+' шаг.</span><span>'+d.sleep+' ч</span></div>';}el.innerHTML='<p>Среднее за '+count+' дн.: '+(count?Math.round(sum/count):'—')+' шагов · '+(count?(sl/count).toFixed(1):'—')+' ч</p>'+html;}
function duDemo(){const h=duData();if(h.demo){for(const k of Object.keys(h.days))if(h.days[k].source==='demo')delete h.days[k];h.demo=false;}else{h.demo=true;for(let i=0;i<14;i++){const t=new Date();t.setDate(t.getDate()-i);const k=t.getFullYear()+'-'+String(t.getMonth()+1).padStart(2,'0')+'-'+String(t.getDate()).padStart(2,'0');if(!h.days[k])h.days[k]={steps:4500+(i*1739)%7000,sleep:6+(i%5)*0.5,stepGoal:h.stepsGoal,sleepGoal:h.sleepGoal,stepAward:false,sleepAward:false,source:'demo'};}}store.set('duHealth',h);duRender();duOpen();}

function duWorkoutDay(key){
 const raw=store.get('fujiHistory',[]),history=Array.isArray(raw)?raw:[];
 const day=r=>r.calendarDate||(r.date&&!Number.isNaN(Date.parse(r.date))?isoDate(new Date(r.date)):'');
 const rows=history.filter(r=>r&&day(r)===key);
 const duration=r=>{const v=Number(r.elapsedSeconds??r.seconds);return Number.isFinite(v)&&v>=0?v:null;};
 let seconds=0,knownTime=0,untimed=0;
 rows.forEach(r=>{const t=duration(r);if(t!==null){seconds+=t;knownTime++;}else untimed++;});
 let count=rows.length;
 const used=new Set();
 for(const [id,c] of Object.entries(completions[key]||{})){
  if(!c?.done)continue;
  const tr=trainings.find(t=>t.id===id),name=tr?.name;
  const idx=rows.findIndex((r,i)=>!used.has(i)&&(r.calendarId===id||(!r.calendarId&&name&&r.name===name)));
  if(idx>=0){used.add(idx);continue;}
  count++;
  if(Number.isFinite(c.elapsedSeconds)&&c.elapsedSeconds>=0){seconds+=c.elapsedSeconds;knownTime++;}
  else untimed++;
 }
 return {seconds,count,knownTime,untimed};
}
