function dvArt(ex){
 const id=ex?.id||''; const name=ex?.name||'';
 const key=id.startsWith('cindy_')?id:/подтягивания/i.test(name)?'cindy_0':/отжимания от пола/i.test(name)?'cindy_1':/^приседания$/i.test(name)?'cindy_2':'';
 const frames=dvReferenceArt[key] || (fujiGuide(ex)?.[2]||[]).slice(0,2).map(f=>f[1]);
 return '<span class="dv-art">'+frames.map((src,i)=>(i?'<i>›</i>':'')+'<img src="'+escapeHtml(src)+'" alt="Фаза '+(i+1)+'">').join('')+(frames.length?'':'<small>Техника в описании</small>')+'</span>';
}
function dvHero(name,limit){return '<div class="dv-hero"><img src="'+dvHeroImage+'" alt="ДаВинчи"><div><small>ДУ / DAVINCI EDITION</small><h2>'+escapeHtml(name)+'</h2><p>'+Math.round(limit/60)+' мин · AMRAP · максимум кругов</p></div></div>';}
function dvRow(a,i,active=false,partial=null){const ex=exercises.find(e=>e.id===a.exId);return '<div class="dv-row '+(active?'active':'')+'"><span class="dv-num">'+(i+1)+'</span><span><b>'+escapeHtml((ex?.name||a.name||'Упражнение').replace(/ · Синди/g,''))+'</b><strong>× '+escapeHtml(a.reps||0)+'</strong>'+(partial!==null?'<small>'+partial+' / '+a.reps+' выполнено</small>':'')+'</span>'+dvArt(ex)+'</div>';}
const dvOldDetail=fujiDetail;
fujiDetail=function(id){dvOldDetail(id);const c=complexes.find(x=>x.id===id);if(id!=='fuji_cindy'||!c)return;document.getElementById('fujiDetailList').innerHTML='<div class="dv-preview">'+dvHero('Комплекс Синди',1200)+'<p class="note">5 подтягиваний · 10 отжиманий · 15 приседаний. Максимум кругов за 20 минут.</p><div class="dv-plan">'+c.exercises.map((a,i)=>{const ex=exercises.find(e=>e.id===a.exId);return '<details><summary>'+dvRow(a,i)+'</summary><p>'+escapeHtml(fujiTechniqueNote(ex))+'</p></details>';}).join('')+'</div></div>';};
const dvOldAmrap=renderAmrap;
renderAmrap=function(){const r=amrapRun;if(!r)return;const screen=document.getElementById('execScreen');screen.classList.add('dv-amrap');const item=r.exercises[r.index];const ex=exercises.find(e=>e.id===item.exId);const phase=r.pausedAt!==null?'Пауза':r.ready?'Работа':'Подготовка';document.getElementById('execProgressTxt').textContent=(r.index+1)+'/'+r.exercises.length+' · '+r.rounds+' кр.';document.getElementById('execBody').innerHTML=dvHero(r.name,r.limit)+'<div class="dv-progress"><div><b>Прогресс по времени</b><span>'+r.rounds+' круг. · '+r.reps+' повт.</span></div><div class="cindy-progress"><i id="amrapBar"></i></div></div><div class="dv-plan">'+r.exercises.map((a,i)=>dvRow(a,i,i===r.index,i===r.index?r.partial:null)).join('')+'</div><div class="dv-clockgrid"><div class="dv-stat">Круги<b>'+r.rounds+'</b></div><div class="dv-ring" id="dvRing"><div class="dv-ring-inner"><small>'+phase+'</small><div class="exec-timer" id="amrapClock"></div><small>Осталось</small></div></div><div class="dv-stat">Общее время<b id="dvElapsed">'+formatWorkoutTime(workoutElapsed())+'</b></div></div><details class="dv-guide"><summary>Техника · '+escapeHtml(ex?.name||'')+'</summary>'+fujiGuideHtml(ex,false)+'</details>';const active=r.ready&&r.pausedAt===null;document.getElementById('execFooter').innerHTML=(active?'<div class="btn-row"><button class="btn" onclick="addAmrapReps(1)">+1 повтор</button><button class="btn btn-primary" onclick="addAmrapReps()">Упражнение готово</button></div>':'')+'<div class="exec-controls"><button class="btn" onclick="toggleAmrapPause()">'+(r.pausedAt===null?'Пауза':'Продолжить')+'</button><button class="btn" onclick="confirmAmrapFinish()">Завершить</button></div>';updateAmrap();};
const dvOldUpdate=updateAmrap;
updateAmrap=function(){dvOldUpdate();const r=amrapRun;if(!r)return;const ring=document.getElementById('dvRing');if(ring){const left=Math.max(0,(r.start+(r.ready?r.limit*1000:0)-(r.pausedAt??Date.now()))/1000);ring.style.setProperty('--pct',(r.ready?Math.min(100,left/r.limit*100):100)+'%');}const elapsed=document.getElementById('dvElapsed');if(elapsed)elapsed.textContent=formatWorkoutTime(workoutElapsed());};
const dvOldFinish=finishAmrap;finishAmrap=function(...args){document.getElementById('execScreen').classList.remove('dv-amrap');return dvOldFinish(...args);};
const dvOldClose=closeExecScreen;closeExecScreen=function(...args){const result=dvOldClose(...args);if(!amrapRun)document.getElementById('execScreen').classList.remove('dv-amrap');return result;};
