/* v22.5: analytics, read-only over saved history */
function du225Metric(r){if(r.mode==='amrap'||r.mode==='reps')return Number(r.reps)||0;if(r.mode==='rounds')return Number(r.rounds)||0;return null;}
function du225Comparable(a,b){return a.id===b.id&&a.mode===b.mode&&a.target===b.target&&a.mode!=='normal'&&(a.mode!=='amrap'||(a.seconds>=a.target&&b.seconds>=b.target));}
function du225Compare(r,history){const v=du225Metric(r);if(v===null)return '';const old=history.filter(x=>du225Comparable(r,x));if(!old.length)return '<p class="note">Нет сопоставимых предыдущих результатов.</p>';const prev=du225Metric(old[0]),best=Math.max(...old.map(du225Metric)),d=v-prev,unit=r.mode==='rounds'?' круг.':' повт.';return '<div class="du225-compare"><b>'+(v>best?'🏆 Новый личный рекорд':'Сравнение с прошлым результатом')+'</b><p>'+ (d>0?'+':'')+d+unit+' · прежний максимум '+best+unit+'</p></div>';}
const du225SummaryOld=fujiSummary;
fujiSummary=function(r){const h=store.get('fujiHistory',[]).filter(x=>new Date(x.date)<new Date(r.date));return '<div class="du225-result"><small>РЕЗУЛЬТАТ ТРЕНИРОВКИ</small><strong>'+formatWorkoutTime(r.elapsedSeconds??r.seconds)+'</strong><span>Общее время</span></div>'+du225Compare(r,h)+du225SummaryOld(r);};
let du225Period=7;
function du225Dashboard(){const el=document.getElementById('du225Dashboard');if(!el)return;const now=new Date(), days=[];for(let i=du225Period-1;i>=0;i--){const d=new Date(now);d.setDate(d.getDate()-i);days.push({key:isoDate(d),seconds:0,count:0});}const h=store.get('fujiHistory',[]);for(const r of h){const d=days.find(x=>x.key===(r.calendarDate||isoDate(new Date(r.date))));if(d){d.seconds+=Math.max(0,Number(r.elapsedSeconds??r.seconds)||0);d.count++;}}const bins=du225Period===365?Array.from({length:13},(_,i)=>days.slice(i*28,i===12?365:(i+1)*28).reduce((a,d)=>({seconds:a.seconds+d.seconds,count:a.count+d.count,key:d.key}),{seconds:0,count:0,key:''})):days;const max=Math.max(1,...bins.map(x=>x.seconds));const total=days.reduce((a,x)=>a+x.seconds,0),count=days.reduce((a,x)=>a+x.count,0);el.innerHTML='<div class="du225-tabs">'+[7,30,365].map(n=>'<button class="btn '+(n===du225Period?'btn-primary':'')+'" onclick="du225Period='+n+';du225Dashboard()">'+({7:'Неделя',30:'Месяц',365:'Год'}[n])+'</button>').join('')+'</div><div class="du225-kpis"><div><b>'+formatWorkoutTime(total)+'</b><small>Время тренировок</small></div><div><b>'+count+'</b><small>Сохранено занятий</small></div></div><div class="du225-bars" role="img" aria-label="Время тренировок по периодам">'+bins.map(x=>'<span title="'+x.key+' · '+formatWorkoutTime(x.seconds)+'" style="height:'+Math.max(3,100*x.seconds/max)+'%"></span>').join('')+'</div><p class="note">'+days[0].key+' — '+days[days.length-1].key+' · '+(du225Period===365?'Группы по 28 дней':'По дням')+'. Только сохранённые результаты.</p>';}
const du225StatsOld=renderStats;renderStats=function(){du225StatsOld();du225Dashboard();};


/* v22.8 — achievements, derived from saved records, no extra XP */
function dv228Awards(){
 const history=store.get('fujiHistory',[]).filter(r=>r&&Number(r.elapsedSeconds??r.seconds)>0&&Number.isFinite(Date.parse(r.date)));
 const days=new Set(history.map(r=>r.calendarDate||isoDate(new Date(r.date))));
 for(const [key,rows] of Object.entries(completions))if(Object.values(rows||{}).some(r=>r?.done&&Number(r.elapsedSeconds)>0))days.add(key);
 const counts=[...days].map(k=>duWorkoutDay(k));
 const sessions=counts.reduce((n,r)=>n+r.count,0), seconds=counts.reduce((n,r)=>n+r.seconds,0);
 const health=Object.values(duData().days).filter(d=>d.source!=='demo');
 const cindy=history.filter(r=>r.id==='fuji_cindy'&&r.mode==='amrap'&&r.target===1200&&r.seconds>=1200&&r.reps>0);
 const best=new Map();let records=0;
 for(const r of [...history].sort((a,b)=>Date.parse(a.date)-Date.parse(b.date))){const v=du225Metric(r);if(v===null||v<=0||(r.mode==='amrap'&&r.seconds<r.target))continue;const k=JSON.stringify([r.id,r.mode,r.target]);if(best.has(k)&&v>best.get(k))records++;best.set(k,Math.max(v,best.get(k)||0));}
 return [
 ['flag','Первый шаг','Сохранённые тренировки',sessions,1],['bolt','В движении','Сохранённые тренировки',sessions,10],['medal','Дисциплина','Сохранённые тренировки',sessions,50],['calendar','Свой ритм','Разные дни с тренировкой',days.size,7],['calendar','Привычка','Разные дни с тренировкой',days.size,30],['clock','Первый час','Минуты тренировок',Math.floor(seconds/60),60],['clock','Десять часов','Минуты тренировок',Math.floor(seconds/60),600],['trophy','Сильнее вчерашнего','Улучшения личного рекорда комплекса',records,1],['bolt','Синди','Полные 20-минутные Синди',cindy.length,1],['medal','Синди × 5','Полные 20-минутные Синди',cindy.length,5],['foot','На своих двоих','Дни с выполненной целью шагов',health.filter(d=>d.steps>=d.stepGoal).length,7],['moon','Восстановление','Дни с выполненной целью сна',health.filter(d=>d.sleep>=d.sleepGoal).length,7],['star','Баланс','Дни с выполненными целями сна и шагов',health.filter(d=>d.steps>=d.stepGoal&&d.sleep>=d.sleepGoal).length,7]];
}
