/* v22.9: saved exercise history, one source per linked session */
function du229Rows(id){
 const ex=exercises.find(e=>e.id===id);if(!ex)return [];
 const out=[], linked=new Set(),hist=store.get('fujiHistory',[]);
 for(const r of hist){if(!r||!Number.isFinite(Date.parse(r.date)))continue;
  const date=r.calendarDate||isoDate(new Date(r.date));
  const items=Array.isArray(r.exerciseStats)?r.exerciseStats:(Array.isArray(r.sets)?r.sets:[]);
  const matches=items.filter(x=>x.exId?x.exId===id:(x.name===ex.name&&exercises.filter(e=>e.name===ex.name).length===1));
  if(!matches.length)continue;
  if(r.calendarId)linked.add(date+'|'+r.calendarId);
  const known=matches.filter(x=>!x.unknown&&x.reps!=null&&Number.isFinite(Number(x.reps)));
  const timed=matches.filter(x=>x.seconds!=null&&Number.isFinite(Number(x.seconds)));
  out.push({date,reps:known.length?known.reduce((n,x)=>n+Number(x.reps),0):null,seconds:timed.length?timed.reduce((n,x)=>n+Number(x.seconds),0):null,source:'Тренировка'});
 }
 for(const [date,day] of Object.entries(completions))for(const [tid,c] of Object.entries(day||{})){
  if(!c?.done||linked.has(date+'|'+tid))continue;
  const items=(c.exercises||[]).filter(x=>x.exId===id);if(!items.length)continue;
  let reps=0,has=false;for(const x of items){const a=x.repsPerSet;if(Array.isArray(a)&&a.length&&a.every(v=>Number.isFinite(Number(v)))){reps+=a.reduce((n,v)=>n+Number(v),0)*(ex.twoSides?2:1);has=true;}else if(Number(x.reps)>0&&Number(x.sets)>0){reps+=Number(x.reps)*Number(x.sets)*(ex.twoSides?2:1);has=true;}}
  out.push({date,reps:has?reps:null,seconds:null,source:'Календарь'});
 }
 return out.sort((a,b)=>b.date.localeCompare(a.date));
}
function du229Draw(id,metric='reps'){
 const el=document.getElementById('du229History');if(!el)return;const rows=du229Rows(id),valid=rows.filter(r=>r[metric]!=null).slice(0,12).reverse(),max=Math.max(1,...valid.map(r=>r[metric]));
 const fmtVal=v=>v==null?'—':metric==='seconds'?formatWorkoutTime(v):String(v);
 el.innerHTML='<details class="card" open><summary><b>Мои результаты · '+rows.length+'</b></summary><div class="btn-row"><button type="button" class="btn btn-sm '+(metric==='reps'?'btn-primary':'')+'" data-m="reps">Повторы</button><button type="button" class="btn btn-sm '+(metric==='seconds'?'btn-primary':'')+'" data-m="seconds">Время работы</button></div>'+ (valid.length?'<p class="note">Максимум: '+fmtVal(Math.max(...valid.map(r=>r[metric])))+' · последние '+valid.length+' записей</p><div style="display:flex;align-items:end;gap:4px;height:80px">'+valid.map(r=>'<div title="'+escapeHtml(r.date)+' · '+fmtVal(r[metric])+'" style="flex:1;background:var(--acc);border-radius:5px;height:'+Math.max(2,r[metric]/max*100)+'%"></div>').join('')+'</div>':'<p class="note">Нет измеренных результатов по этому показателю.</p>')+rows.slice(0,12).map(r=>'<div class="exercise-item">'+escapeHtml(r.date)+' · '+(r.reps==null?'—':r.reps+' повт.')+' · '+(r.seconds==null?'—':formatWorkoutTime(r.seconds))+'</div>').join('')+'</details>';
 el.querySelectorAll('[data-m]').forEach(b=>b.onclick=()=>du229Draw(id,b.dataset.m));
}
const du229OpenOld=openExModal;openExModal=function(id){du229OpenOld(id);if(id)du229Draw(id);else document.getElementById('du229History').innerHTML='';};


/* v23.0: existing anatomical taxonomy, interactive schematic */
function du230Map(){const el=document.getElementById('du230MapBody');if(!el)return;
 const main=zones.filter(z=>z.isMain||!z.parent);const selected=filterZones;
 el.innerHTML='<p class="note">Схематические зоны из базы. Выбери область тела или снаряд.</p><div style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px">'+main.map((z,i)=>'<button type="button" class="btn btn-sm '+(selected.includes(z.id)?'btn-primary':'')+'" data-zone="'+i+'" style="display:flex;flex-direction:column;align-items:center;gap:4px;min-height:76px">'+E(z)+'<span>'+escapeHtml(z.name)+'</span></button>').join('')+'</div><div class="field-group"><label class="field-label">Снаряд</label><select class="field-input" id="du230Gear"><option value="">Все</option>'+gears.map((g,i)=>'<option value="'+i+'" '+(filterGears.length===1&&filterGears[0]===g.id?'selected':'')+'>'+escapeHtml(g.name)+'</option>').join('')+'</select></div><button class="btn btn-sm btn-full" id="du230Reset">Сбросить фильтры</button>';
 el.querySelectorAll('[data-zone]').forEach(b=>b.onclick=()=>{const id=main[Number(b.dataset.zone)].id;filterZones=filterZones.includes(id)?filterZones.filter(x=>x!==id):[...filterZones,id];renderChips();renderEx();});
 el.querySelector('#du230Gear').onchange=e=>{filterGears=e.target.value===''?[]:[gears[Number(e.target.value)].id];renderChips();renderEx();};
 el.querySelector('#du230Reset').onclick=()=>{filterZones=[];filterGears=[];filterSkills=[];renderChips();renderEx();};
}
const du230ExOld=renderEx;renderEx=function(){du230ExOld();du230Map();};


/* v23.1: calendar + free sessions, deduplicated by existing day aggregator */
let du231Period=7;
function du231Days(n){return Array.from({length:n},(_,i)=>{const d=new Date();d.setDate(d.getDate()-n+1+i);const key=isoDate(d);return {key,...duWorkoutDay(key)};});}
function du231Render(){
 const el=document.getElementById('du231Load');if(!el)return;
 const days=du231Days(du231Period),prev=du231Days(du231Period*2).slice(0,du231Period);
 const sum=a=>a.reduce((n,d)=>n+d.seconds,0),total=sum(days),before=sum(prev);
 const sessions=days.reduce((n,d)=>n+d.count,0),untimed=days.reduce((n,d)=>n+d.untimed,0);
 const max=Math.max(1,...days.map(d=>d.seconds));
 el.innerHTML='<b>Тренировочная нагрузка</b><div class="btn-row">'+[7,30].map(n=>'<button class="btn btn-sm '+(n===du231Period?'btn-primary':'')+'" onclick="du231Period='+n+';du231Render()">'+n+' дней</button>').join('')+'</div>'+
 '<div class="du225-kpis"><div><b>'+formatWorkoutTime(total)+'</b><small>Общее учтённое время</small></div><div><b>'+sessions+'</b><small>Занятий (включая ручные)</small></div></div>'+
 '<div class="du225-bars">'+days.map(d=>'<span title="'+d.key+' · '+d.count+' занятий · '+formatWorkoutTime(d.seconds)+'" class="'+(d.count&&!d.seconds?'du-manual-bar':'')+'" style="height:'+Math.max(d.count?10:2,d.seconds/max*100)+'%"></span>').join('')+'</div>'+
 '<p class="note">Активных дней: '+days.filter(d=>d.count>0).length+' · предыдущий период: '+formatWorkoutTime(before)+(before?' · изменение '+Math.round((total-before)/before*100)+'%':'')+'</p>'+
 (untimed?'<p class="note du-manual-note">✓ Учтено '+untimed+' ручных отметок без таймера. Они входят в количество занятий и активных дней, но не в минуты: продолжительность не указана.</p>':'')+
 '<p class="note">Время включает таймер и вручную указанную продолжительность, включая отдых и подготовку. Это не оценка физиологической нагрузки.</p>';
}
const du231StatsOld=renderStats;renderStats=function(){du231StatsOld();du231Render();};


/* v23.2: optional subjective recovery journal; no XP */
function du232Data(){return store.get('duRecovery',{})||{};}
function du232Render(){const el=document.getElementById('du232Recovery');if(!el)return;const d=du232Data()[duDay()]||{};const labels=['Очень низко','Низко','Средне','Хорошо','Отлично'];const options=(v,fatigue=false)=>'<option value="">Не указано</option>'+(fatigue?['Нет','Лёгкая','Умеренная','Сильная','Очень сильная']:labels).map((l,i)=>'<option value="'+(i+1)+'" '+(v===i+1?'selected':'')+'>'+l+'</option>').join('');el.innerHTML='<p class="note">Необязательная личная отметка. Без XP и медицинских оценок.</p><div class="field-group"><label class="field-label">Энергия</label><select class="field-input" id="du232Energy">'+options(d.energy)+'</select></div><div class="field-group"><label class="field-label">Качество сна</label><select class="field-input" id="du232Sleep">'+options(d.sleep)+'</select></div><div class="field-group"><label class="field-label">Мышечная усталость</label><select class="field-input" id="du232Fatigue">'+options(d.fatigue,true)+'</select></div><button class="btn btn-full" onclick="du232Save()">Сохранить отметку</button><details><summary>Последние отметки</summary>'+Object.entries(du232Data()).sort((a,b)=>b[0].localeCompare(a[0])).slice(0,7).map(([k,v])=>'<p class="note">'+escapeHtml(k)+' · энергия '+(v.energy||'—')+'/5 · сон '+(v.sleep||'—')+'/5 · усталость '+(v.fatigue||'—')+'/5</p>').join('')+'</details>';}
function du232Save(){const h=du232Data(),read=id=>Number(document.getElementById(id).value)||null;h[duDay()]={energy:read('du232Energy'),sleep:read('du232Sleep'),fatigue:read('du232Fatigue')};store.set('duRecovery',h);du232Render();toast('Отметка сохранена');}
