/* v23.3: explicit offline bridge, daily aggregates only, no direct HealthKit access */
let du233Pending=[];
function du233Parse(data){if(!data||data.schema!=='du.health.daily.v1'||!Array.isArray(data.days)||data.days.length>3660)throw Error('Нужен JSON формата du.health.daily.v1 (до 3660 дней)');const seen=new Set();return data.days.map(d=>{if(!d||typeof d.date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(d.date)||!Number.isFinite(Date.parse(d.date+'T12:00:00'))||isoDate(new Date(d.date+'T12:00:00'))!==d.date||d.date>duDay()||seen.has(d.date))throw Error('Некорректная или повторная дата');seen.add(d.date);if(!Number.isInteger(d.steps)||d.steps<0||d.steps>100000||typeof d.sleepHours!=='number'||!Number.isFinite(d.sleepHours)||d.sleepHours<0||d.sleepHours>24)throw Error('Некорректные шаги или часы сна');return {date:d.date,steps:d.steps,sleep:d.sleepHours};});}
function du233Render(){const el=document.getElementById('du233Bridge');if(!el)return;el.innerHTML='<p class="note">Прямое подключение часов пока недоступно. Можно импортировать дневные итоги из подготовленного JSON. Существующие реальные записи не заменяются. Импорт не начисляет XP автоматически.</p><input type="file" accept=".json,application/json" id="du233File" class="field-input"><button class="btn btn-full" onclick="du233Example()">Скачать пример формата</button><div id="du233Preview"></div>';el.querySelector('input').onchange=async e=>{du233Pending=[];const p=document.getElementById('du233Preview');try{const f=e.target.files[0];if(!f)return;if(f.size>2000000)throw Error('Файл слишком большой');du233Pending=du233Parse(JSON.parse(await f.text()));p.textContent='Проверено дней: '+du233Pending.length;const b=document.createElement('button');b.className='btn btn-primary btn-full';b.textContent='Импортировать новые дни';b.onclick=du233Apply;p.appendChild(b);}catch(err){p.textContent=err.message;}};}
function du233Apply(){const h=duData();let added=0;for(const d of du233Pending){const old=h.days[d.date];if(old&&old.source!=='demo')continue;h.days[d.date]={steps:d.steps,sleep:d.sleep,stepGoal:h.stepsGoal,sleepGoal:h.sleepGoal,stepAward:false,sleepAward:false,source:'import'};added++;}store.set('duHealth',h);du233Pending=[];duRender();renderHome();toast('Импортировано дней: '+added+' · без XP');}
function du233Example(){const data={schema:'du.health.daily.v1',days:[{date:duDay(),steps:0,sleepHours:0}]};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='du-health-example.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const du233HomeOld=renderHome;renderHome=function(){du233HomeOld();du233Render();const d=duData().days[duDay()];if(d?.source==='import')document.getElementById('liveSource').textContent='Шаги и сон · импорт JSON';};


/* v23.4 — actual set values, optional effort, previous results */
function du234Edit(){const st=execState;if(!st||st.summary||st.finishingSet)return;const it=st.exercises[st.currentIndex];if(!it||it.type==='rounds')return;const old=st.du234Override||{};const box=document.getElementById('du234Fields');if(!box)return;box.hidden=!box.hidden;}
function du234Set(field,value){const st=execState;if(!st||st.summary||st.finishingSet)return;st.du234Override=st.du234Override||{};if(value===''){delete st.du234Override[field];return;}const n=Number(value);if(!Number.isFinite(n)||n<0)return;st.du234Override[field]=field==='reps'?Math.min(100000,Math.floor(n)):field==='rpe'?Math.max(1,Math.min(10,Math.round(n))):Math.min(1000,n);}
const du234Old=renderExecScreen;renderExecScreen=function(){const result=du234Old.apply(this,arguments);const st=execState,focus=document.querySelector('#execBody .exec-focus');if(!st||st.summary||!focus)return result;const it=st.exercises[st.currentIndex];if(!it||it.type==='rounds')return result;const prev=du229Rows(it.exId)[0],o=st.du234Override||{};const div=document.createElement('div');div.className='exercise-item';div.style.margin='8px 0';const last=prev?('Прошлый раз: '+(prev.reps==null?'—':prev.reps+' повт.')+' · '+(prev.seconds==null?'—':fmt(prev.seconds))):'Первое занятие с этим упражнением';div.innerHTML='<small>'+escapeHtml(last)+'</small><button class="btn btn-full" onclick="du234Edit()">Фактические повторы / вес / усилие</button><div id="du234Fields" hidden><label>Повторы '+(it.twoSides?'на сторону':'за подход')+'<input class="field-input" type="number" min="0" step="1" value="'+(o.reps??'')+'" placeholder="'+(Number(it.reps)||0)+'" onchange="du234Set(\'reps\',this.value)"></label><label>Вес, кг<input class="field-input" type="number" min="0" step="0.1" value="'+(o.weight??'')+'" placeholder="'+(Number(it.weight)||0)+'" onchange="du234Set(\'weight\',this.value)"></label><label>Усилие (1–10, необязательно)<input class="field-input" type="number" min="1" max="10" step="1" value="'+(o.rpe??'')+'" onchange="du234Set(\'rpe\',this.value)"></label><small>Пустое поле — значение по плану. Изменения только для текущего подхода.</small></div>';focus.append(div);return result;};
const du234Step=stepExecExercise;stepExecExercise=function(){if(execState)execState.du234Override=null;return du234Step.apply(this,arguments);};
const du234Summary=fujiSummary;fujiSummary=function(r){const html=du234Summary(r);const rows=(r.sets||[]).filter(x=>x.rpe!=null||x.weight>0);return html+(rows.length?'<details class="exercise-item"><summary>Вес и усилие по подходам</summary>'+rows.map(x=>'<p>'+escapeHtml(x.name)+' · '+(x.weight??0)+' кг'+(x.rpe!=null?' · усилие '+x.rpe+'/10':'')+'</p>').join('')+'</details>':'');};

/* v23.5 — offline coach, curated exercise IDs, editable calendar draft */
let duCoachDraft=null;
const duCoachCatalog=[['mwmljs66slmwz','legs','none',8],['mwmljs66bu619','push','none',5],['mwmljs66xyawv','hinge','none',10],['mwmljs6629zha','core','none',20],['mwmljs66y44iu','legs','none',10],['bone_ex_13','balance','none',20],['mwmljs66ruiu4','mobility','none',10],['mwmljs65lr6gd','cardio','rope',30],['bone_ex_1','legs','kb',8],['bone_ex_2','hinge','kb',8],['mwmljs66n44eq','push','kb',5],['bone_ex_17','pull','rings',6],['mwmljs66efro3','pull','pullup',3]];
function duCoachPlan(goal,minutes,level,gear,kg,recovery){
 const easy=level==='beginner'||recovery, order=goal==='cardio'?['cardio','legs','push','hinge','core','balance','mobility','pull']:goal==='light'?['mobility','balance','hinge','core','legs']:['legs','pull','push','hinge','core','balance','mobility'];
 const pool=duCoachCatalog.filter(r=>gear.includes(r[2])&&exercises.some(e=>e.id===r[0])&&(r[2]!=='kb'||kg>0));
 const rows=[];let used=0;const budget=(minutes-5)*60;
 for(const group of order){const candidates=pool.filter(r=>r[1]===group);const r=candidates.find(r=>r[2]!=='none')||candidates[0];if(!r)continue;const ex=exercises.find(e=>e.id===r[0]);const timed=ex.format==='time';const sets=goal==='light'||recovery?1:easy?2:3;const reps=timed?0:r[3];const time=timed?r[3]:0;const rest=goal==='cardio'?45:60;const cost=sets*((timed?time:reps*4)*(ex.twoSides?2:1)+rest+15);if(used+cost>budget)continue;used+=cost;rows.push({exId:ex.id,sets,reps,time,rest,weight:r[2]==='kb'?kg:0,note:'DaVinci Coach · комфортная техника, без отказа'});}
 return {rows,minutes:Math.ceil(used/60)+5};
}
function duCoachGenerate(){const el=id=>document.getElementById(id),goal=el('duCoachGoal').value,minutes=Number(el('duCoachMinutes').value),level=el('duCoachLevel').value,gear=['none',...Array.from(document.querySelectorAll('#duCoachGear input:checked'),x=>x.value)],kg=Number(el('duCoachKg').value),recovery=el('duCoachRecovery').checked;const out=el('duCoachResult');duCoachDraft=null;if(gear.includes('kb')&&(!Number.isFinite(kg)||kg<=0||kg>100)){out.textContent='Укажи знакомый комфортный вес гири (1–100 кг).';return;}const plan=duCoachPlan(goal,minutes,level,gear,kg,recovery);if(!plan.rows.length){out.textContent='Нет подходящих упражнений. Проверь библиотеку или увеличь время.';return;}duCoachDraft={...plan,goal};out.innerHTML='<div class="exercise-item"><b>План · около '+plan.minutes+' мин</b><p class="note">Включая 3 мин лёгкой разминки и 2 мин заминки самостоятельно. Время приблизительное.</p>'+plan.rows.map(r=>{const e=exercises.find(x=>x.id===r.exId);return '<p style="margin:8px 0">'+escapeHtml(e.name)+' · '+r.sets+' × '+(r.time?r.time+' сек':r.reps+' повт.')+(e.twoSides?' на сторону':'')+(r.weight?' · '+r.weight+' кг':'')+' · отдых '+r.rest+' сек</p>';}).join('')+'<button class="btn btn-primary btn-full" onclick="duCoachCalendar()">Открыть черновик в календаре</button></div>';}
function duCoachCalendar(){if(!duCoachDraft)return;if(!duCoachDraft.rows.every(r=>exercises.some(e=>e.id===r.exId))){toast('Библиотека изменилась. Создай план заново.');return;}const draft=duCoachDraft;selectDate(new Date());navTo('v-main');openTrainModal();document.getElementById('tName').value='DaVinci Coach · '+({strength:'Сила',cardio:'Выносливость',light:'Лёгкая активность'}[draft.goal]);tempTrainEx=JSON.parse(JSON.stringify(draft.rows));renderTempTrainEx();updateTrainSchedule();}
function duCoachInit(){const el=document.getElementById('duCoachCard');if(!el||el.dataset.ready)return;el.dataset.ready='1';el.innerHTML='<summary><b>DaVinci Coach</b> · персональный план</summary><p class="note">Автономный конструктор по правилам, не нейросеть. Для взрослых без противопоказаний. При боли или плохом самочувствии отложи занятие.</p><div class="field-group"><label class="field-label" for="duCoachGoal">Цель</label><select class="field-input" id="duCoachGoal"><option value="strength">Сила · всё тело</option><option value="cardio">Выносливость</option><option value="light">Лёгкая активность</option></select></div><div class="field-group"><label class="field-label" for="duCoachMinutes">Доступное время</label><select class="field-input" id="duCoachMinutes"><option value="15">15 минут</option><option value="25" selected>25 минут</option><option value="40">40 минут</option></select></div><div class="field-group"><label class="field-label" for="duCoachLevel">Опыт</label><select class="field-input" id="duCoachLevel"><option value="beginner">Начинающий</option><option value="regular">Регулярно тренируюсь</option></select></div><div id="duCoachGear" class="field-group"><b>Оборудование</b><p class="note">Собственный вес и свободное место доступны по умолчанию.</p>'+[['kb','Гиря'],['rope','Скакалка'],['rings','Кольца'],['pullup','Турник']].map(([v,n])=>'<label style="display:block;padding:6px"><input type="checkbox" value="'+v+'"> '+n+'</label>').join('')+'</div><label>Знакомый рабочий вес гири, кг<input class="field-input" id="duCoachKg" type="number" min="1" max="100" step="0.5" placeholder="Не выбран"></label><label style="display:block;margin:10px 0"><input id="duCoachRecovery" type="checkbox"> Сегодня нужна облегчённая нагрузка</label><button class="btn btn-primary btn-full" onclick="duCoachGenerate()">Составить тренировку</button><div id="duCoachResult" aria-live="polite"></div>';el.addEventListener('change',()=>{duCoachDraft=null;document.getElementById('duCoachResult').textContent='';});}
const duCoachHomeOld=renderHome;renderHome=function(){duCoachHomeOld();duCoachInit();};

