/* v23.6.2: presentation-only grouping, original IDs remain intact */
const duFolderOpen={library:new Set(),picker:new Set()};
function duFolderName(c){const name=String(c.name||'');const parts=name.split(/\s+·\s+/);return parts.length>1?parts[0].trim():'';}
function duFolderRender(el,q,mode){
 const groups=new Map();for(const c of complexes){const key=duFolderName(c);if(key){if(!groups.has(key))groups.set(key,[]);groups.get(key).push(c);}}
 const matches=complexes.filter(c=>String(c.name||'').toLowerCase().includes(q));
 if(mode==='library')document.getElementById('compsCount').textContent=matches.length;
 el.replaceChildren();const emitted=new Set();
 const row=(c,short)=>{const b=document.createElement('button');b.type='button';b.className='fuji-compact';const name=short?String(c.name).split(/\s+·\s+/).slice(1).join(' · '):c.name;b.innerHTML=fujiPic(exercises.find(e=>e.id===c.exercises[0]?.exId))+'<span><b>'+escapeHtml(name)+'</b><small>'+c.exercises.length+' упражнений · '+(c.roundMode?'круговая':'комплекс')+'</small></span><strong>'+(mode==='picker'?'+':'›')+'</strong>';b.onclick=()=>mode==='picker'?pickComplex(c.id):fujiDetail(c.id);return b;};
 for(const c of matches){const key=duFolderName(c),all=groups.get(key);if(!key||!all||all.length<2){el.append(row(c,false));continue;}if(emitted.has(key))continue;emitted.add(key);const visible=matches.filter(x=>duFolderName(x)===key);const d=document.createElement('details');d.className='card du-comp-folder';d.open=!!q||duFolderOpen[mode].has(key);const summary=document.createElement('summary');summary.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"><path d="M3 6h7l2 3h9v11H3z"/></svg><span><b>'+escapeHtml(key)+'</b><small>'+all.length+' тренировок'+(q?' · найдено '+visible.length:'')+'</small></span>';d.append(summary);const body=document.createElement('div');body.className='du-folder-items';visible.forEach(x=>body.append(row(x,true)));d.append(body);d.addEventListener('toggle',()=>{if(!q){if(d.open)duFolderOpen[mode].add(key);else duFolderOpen[mode].delete(key);}});el.append(d);}
 if(!matches.length){const p=document.createElement('p');p.className='note';p.textContent=q?'Ничего не найдено':'Комплексов пока нет';el.append(p);}
}
